import { service } from ".";

export const fetchLatestAppVersion = () => {
  return new Promise((resolve, reject) => {
    service({
      url: "/app-version",
      method: "GET",
    })
      .then(async (res) => await resolve(res.data))
      .catch((error) => reject(error));
  });
};

export const createAppVersion = (data) => {
  return new Promise((resolve, reject) => {
    service({
      url: "/app-version",
      method: "POST",
      data,
    })
      .then(async (res) => await resolve(res.data))
      .catch((error) => reject(error));
  });
};

