import React, { useMemo, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Container,
  Paper,
  Stack,
  TextField,
  Typography,
} from "@mui/material";
import Header from "../../../components/AdminHeader";
import LeftBar from "../../../components/AdminLeftBar";
import { fetchMemberList } from "../../../../src/api/User";
import { fetchOrderList } from "../../../../src/api/Order";

const safeJson = (value) => {
  try {
    return JSON.stringify(value, null, 2);
  } catch {
    return String(value);
  }
};

const ApiGet = () => {
  const [memberParams, setMemberParams] = useState({
    keyword: "",
    page: 1,
    limit: 10,
  });
  const [orderParams, setOrderParams] = useState({
    purchaseType: "",
    payType: "",
    begin_date: "",
    end_date: "",
    page: 1,
    limit: 10,
  });

  const [memberState, setMemberState] = useState({
    loading: false,
    error: "",
    data: null,
  });
  const [orderState, setOrderState] = useState({
    loading: false,
    error: "",
    data: null,
  });

  const memberRequestParams = useMemo(() => {
    const params = {};
    if (memberParams.keyword) params.keyword = memberParams.keyword;
    if (memberParams.page) params.page = Number(memberParams.page);
    if (memberParams.limit) params.limit = Number(memberParams.limit);
    return params;
  }, [memberParams]);

  const orderRequestParams = useMemo(() => {
    const params = {};
    if (orderParams.purchaseType) params.purchaseType = orderParams.purchaseType;
    if (orderParams.payType) params.payType = orderParams.payType;
    if (orderParams.begin_date) params.begin_date = orderParams.begin_date;
    if (orderParams.end_date) params.end_date = orderParams.end_date;
    if (orderParams.page) params.page = Number(orderParams.page);
    if (orderParams.limit) params.limit = Number(orderParams.limit);
    params.order = "desc";
    params.sort = "id";
    return params;
  }, [orderParams]);

  const callMember = async () => {
    setMemberState({ loading: true, error: "", data: null });
    try {
      const data = await fetchMemberList(memberRequestParams);
      setMemberState({ loading: false, error: "", data });
    } catch (err) {
      const message =
        err?.response?.data?.message || err?.message || "fetchMemberList failed";
      setMemberState({ loading: false, error: message, data: null });
    }
  };

  const callOrder = async () => {
    setOrderState({ loading: true, error: "", data: null });
    try {
      const data = await fetchOrderList(orderRequestParams);
      setOrderState({ loading: false, error: "", data });
    } catch (err) {
      const message =
        err?.response?.data?.message || err?.message || "fetchOrderList failed";
      setOrderState({ loading: false, error: message, data: null });
    }
  };

  return (
    <>
      <Header />
      <LeftBar />
      <Container maxWidth="xl" sx={{ mt: 10, ml: { md: "180px" } }}>
        <Typography variant="h5" sx={{ mb: 2 }}>
          API GET 測試頁
        </Typography>

        <Stack spacing={2}>
          <Paper elevation={0} sx={{ p: 2, border: "1px solid #eee" }}>
            <Stack
              direction={{ xs: "column", md: "row" }}
              spacing={2}
              alignItems={{ md: "center" }}
              justifyContent="space-between"
            >
              <Box sx={{ flex: 1 }}>
                <Typography sx={{ fontWeight: 600, mb: 1 }}>
                  GET /bo/member（fetchMemberList）
                </Typography>
                <Stack direction={{ xs: "column", sm: "row" }} spacing={2}>
                  <TextField
                    label="keyword"
                    value={memberParams.keyword}
                    onChange={(e) =>
                      setMemberParams((prev) => ({
                        ...prev,
                        keyword: e.target.value,
                      }))
                    }
                    fullWidth
                  />
                  <TextField
                    label="page"
                    type="number"
                    value={memberParams.page}
                    onChange={(e) =>
                      setMemberParams((prev) => ({
                        ...prev,
                        page: e.target.value,
                      }))
                    }
                    sx={{ width: { sm: 140 } }}
                  />
                  <TextField
                    label="limit"
                    type="number"
                    value={memberParams.limit}
                    onChange={(e) =>
                      setMemberParams((prev) => ({
                        ...prev,
                        limit: e.target.value,
                      }))
                    }
                    sx={{ width: { sm: 140 } }}
                  />
                </Stack>
              </Box>

              <Button
                variant="contained"
                onClick={callMember}
                disabled={memberState.loading}
              >
                {memberState.loading ? "呼叫中..." : "呼叫"}
              </Button>
            </Stack>

            {!!memberState.error && (
              <Alert severity="error" sx={{ mt: 2 }}>
                {memberState.error}
              </Alert>
            )}

            <Box sx={{ mt: 2 }}>
              <Typography sx={{ fontWeight: 600, mb: 1 }}>Request</Typography>
              <Box
                component="pre"
                sx={{
                  m: 0,
                  p: 2,
                  borderRadius: 1,
                  backgroundColor: "#fafafa",
                  overflow: "auto",
                  fontSize: 12,
                }}
              >
                {safeJson(memberRequestParams)}
              </Box>
            </Box>

            <Box sx={{ mt: 2 }}>
              <Typography sx={{ fontWeight: 600, mb: 1 }}>Response</Typography>
              <Box
                component="pre"
                sx={{
                  m: 0,
                  p: 2,
                  borderRadius: 1,
                  backgroundColor: "#fafafa",
                  overflow: "auto",
                  fontSize: 12,
                  minHeight: 120,
                }}
              >
                {memberState.data ? safeJson(memberState.data) : ""}
              </Box>
            </Box>
          </Paper>

          <Paper elevation={0} sx={{ p: 2, border: "1px solid #eee" }}>
            <Stack
              direction={{ xs: "column", md: "row" }}
              spacing={2}
              alignItems={{ md: "center" }}
              justifyContent="space-between"
            >
              <Box sx={{ flex: 1 }}>
                <Typography sx={{ fontWeight: 600, mb: 1 }}>
                  GET /bo/purchase（fetchOrderList）
                </Typography>
                <Stack direction={{ xs: "column", md: "row" }} spacing={2}>
                  <TextField
                    label="purchaseType"
                    placeholder="WAIT / ACCEPT / DOING / SUCCESS / CANCEL"
                    value={orderParams.purchaseType}
                    onChange={(e) =>
                      setOrderParams((prev) => ({
                        ...prev,
                        purchaseType: e.target.value,
                      }))
                    }
                    fullWidth
                  />
                  <TextField
                    label="payType"
                    placeholder="NO_PAY / SUCCESS / FAIL / APPLY_REFUND / REFUND"
                    value={orderParams.payType}
                    onChange={(e) =>
                      setOrderParams((prev) => ({
                        ...prev,
                        payType: e.target.value,
                      }))
                    }
                    fullWidth
                  />
                </Stack>

                <Stack
                  direction={{ xs: "column", sm: "row" }}
                  spacing={2}
                  sx={{ mt: 2 }}
                >
                  <TextField
                    label="begin_date"
                    placeholder="yyyy-MM-dd"
                    value={orderParams.begin_date}
                    onChange={(e) =>
                      setOrderParams((prev) => ({
                        ...prev,
                        begin_date: e.target.value,
                      }))
                    }
                    fullWidth
                  />
                  <TextField
                    label="end_date"
                    placeholder="yyyy-MM-dd"
                    value={orderParams.end_date}
                    onChange={(e) =>
                      setOrderParams((prev) => ({
                        ...prev,
                        end_date: e.target.value,
                      }))
                    }
                    fullWidth
                  />
                  <TextField
                    label="page"
                    type="number"
                    value={orderParams.page}
                    onChange={(e) =>
                      setOrderParams((prev) => ({
                        ...prev,
                        page: e.target.value,
                      }))
                    }
                    sx={{ width: { sm: 140 } }}
                  />
                  <TextField
                    label="limit"
                    type="number"
                    value={orderParams.limit}
                    onChange={(e) =>
                      setOrderParams((prev) => ({
                        ...prev,
                        limit: e.target.value,
                      }))
                    }
                    sx={{ width: { sm: 140 } }}
                  />
                </Stack>
              </Box>

              <Button
                variant="contained"
                onClick={callOrder}
                disabled={orderState.loading}
              >
                {orderState.loading ? "呼叫中..." : "呼叫"}
              </Button>
            </Stack>

            {!!orderState.error && (
              <Alert severity="error" sx={{ mt: 2 }}>
                {orderState.error}
              </Alert>
            )}

            <Box sx={{ mt: 2 }}>
              <Typography sx={{ fontWeight: 600, mb: 1 }}>Request</Typography>
              <Box
                component="pre"
                sx={{
                  m: 0,
                  p: 2,
                  borderRadius: 1,
                  backgroundColor: "#fafafa",
                  overflow: "auto",
                  fontSize: 12,
                }}
              >
                {safeJson(orderRequestParams)}
              </Box>
            </Box>

            <Box sx={{ mt: 2 }}>
              <Typography sx={{ fontWeight: 600, mb: 1 }}>Response</Typography>
              <Box
                component="pre"
                sx={{
                  m: 0,
                  p: 2,
                  borderRadius: 1,
                  backgroundColor: "#fafafa",
                  overflow: "auto",
                  fontSize: 12,
                  minHeight: 120,
                }}
              >
                {orderState.data ? safeJson(orderState.data) : ""}
              </Box>
            </Box>
          </Paper>
        </Stack>
      </Container>
    </>
  );
};

export default ApiGet;

