// api/MemberAPI.js
import { service } from "."; // 路徑依專案調整

/**
 * 1. 取得會員列表 (GET /bo/member)
 *   - 可帶 query 參數：user_id, role_id, keyword, page, limit, order, sort
 */
export const fetchMemberList = (params = {}) => {
  return new Promise((resolve, reject) => {
    // 組合 query string
    let url = "/bo/member?";
    const queryParams = [];

    if (params.user_id) queryParams.push("user_id=" + params.user_id);
    if (params.role_id) queryParams.push("role_id=" + params.role_id);
    if (params.keyword) queryParams.push("keyword=" + params.keyword);
    if (params.page) queryParams.push("page=" + params.page);
    if (params.limit) queryParams.push("limit=" + params.limit);
    if (params.order) queryParams.push("order=" + params.order);
    if (params.sort) queryParams.push("sort=" + params.sort);

    url += queryParams.join("&");

    service({
      url,
      method: "GET",
    })
      .then(async (res) => await resolve(res.data))
      .catch((err) => reject(err));
  });
};

