import Switch from "@mui/material/Switch";
import React, { useEffect, useState } from "react";
import { fetchOrderList, forceSuccessPurchase, updatePurchaseIsCharge } from "../../../../src/api/Order"; // 依實際路徑
import Header from "../../../components/AdminHeader";
import LeftBar from "../../../components/AdminLeftBar";

import {
  Alert,
  Box,
  Button,
  Container,
  MenuItem,
  Paper,
  Select,
  Snackbar,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  Typography
} from "@mui/material";
import { format } from "date-fns";

import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css"; // 要記得引入 CSS

const OrderManagement = () => {
  // 篩選條件
  const [purchaseType, setPurchaseType] = useState("");
  const [payType, setPayType] = useState("");
  const [beginDate, setBeginDate] = useState(new Date());
  const [endDate, setEndDate] = useState(new Date());
  const [isChargeFilter, setIsChargeFilter] = useState("");


  // 分頁
  const [page, setPage] = useState(0);
  const [limit, setLimit] = useState(10);
  const [totalCount, setTotalCount] = useState(0);

  // 訂單列表
  const [orderList, setOrderList] = useState([]);
  const [forcingPurchaseId, setForcingPurchaseId] = useState(null);

  // Snackbar
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMsg, setSnackbarMsg] = useState("");
  const [snackbarSeverity, setSnackbarSeverity] = useState("success");

  const showSnackbar = (message, severity = "info") => {
    setSnackbarMsg(message);
    setSnackbarSeverity(severity);
    setSnackbarOpen(true);
  };
  const handleCloseSnackbar = () => {
    setSnackbarOpen(false);
  };

  // 取得訂單列表
  const getOrders = async () => {
    try {
      const pageIndex = page + 1;

      const res = await fetchOrderList({
        purchaseType,
        payType,
        begin_date: beginDate ? format(beginDate, "yyyy-MM-dd") : undefined,
        end_date: endDate ? format(endDate, "yyyy-MM-dd") : undefined,
        is_charge: isChargeFilter !== "" ? isChargeFilter === "true" : undefined,
        page: pageIndex,
        limit,
        order: "desc",
        sort: "id",
      });

      if (res?.success) {
        const records = res.data?.records || [];
        setOrderList(records);

        const pageObj = res.data?.page || {};
        setTotalCount(pageObj.total_count || 0);
      } else {
        showSnackbar("取得訂單失敗", "error");
      }
    } catch (error) {
      console.error("getOrders error:", error);
      showSnackbar("取得訂單發生錯誤", "error");
    }
  };
  // 新增控制 is_charge 的方法
  const handleToggleIsCharge = async (purchaseId, newValue) => {
    try {
      const res = await updatePurchaseIsCharge(
        purchaseId,
        newValue
      );
      if (res?.success) {
        getOrders()
      } else {
        showSnackbar("更改失敗", "error");
      }
    } catch (error) {
      console.error("getOrders error:", error);
      showSnackbar("更改失敗", "error");
    }
  };

  const handleForcePurchaseSuccess = async (purchaseId) => {
    const confirmed = window.confirm("確定要強制將這筆訂單結單為 SUCCESS 嗎？");
    if (!confirmed) return;

    setForcingPurchaseId(purchaseId);
    try {
      const res = await forceSuccessPurchase(purchaseId);
      if (res?.success) {
        showSnackbar("訂單已強制結單", "success");
        getOrders();
      } else {
        showSnackbar(res?.message || "強制結單失敗", "error");
      }
    } catch (error) {
      console.error("forceSuccessPurchase error:", error);
      showSnackbar(error?.response?.data?.message || "強制結單失敗", "error");
    } finally {
      setForcingPurchaseId(null);
    }
  };
  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };
  const handleChangeRowsPerPage = (event) => {
    setLimit(parseInt(event.target.value, 10));
    setPage(0);
  };

  useEffect(() => {
    getOrders();
  }, [page, limit, purchaseType, payType]);

  const handleSearch = () => {
    setPage(0);
    getOrders();
  };

  return (
    <>
      <Header />
      <LeftBar />

      <Container maxWidth="lg" sx={{ pt: 10, pb: 4 }}>
        <Paper sx={{ p: 2, mb: 4 }}>
          <Typography variant="h4" sx={{ mb: 2, fontWeight: 600 }}>
            訂單管理
          </Typography>

          {/* 篩選條件 */}
          <Box mb={2}>
            <Stack direction="row" spacing={2} alignItems="center" flexWrap="wrap">
              {/* purchaseType 下拉 */}
              <Select
                size="small"
                value={purchaseType}
                onChange={(e) => setPurchaseType(e.target.value)}
                displayEmpty
              >
                <MenuItem value="">全部狀態</MenuItem>
                <MenuItem value="WAIT">WAIT</MenuItem>
                <MenuItem value="ACCEPT">ACCEPT</MenuItem>
                <MenuItem value="DOING">DOING</MenuItem>
                <MenuItem value="SUCCESS">SUCCESS</MenuItem>
                <MenuItem value="CANCEL">CANCEL</MenuItem>
              </Select>

              {/* payType 下拉 */}
              <Select
                size="small"
                value={payType}
                onChange={(e) => setPayType(e.target.value)}
                displayEmpty
              >
                <MenuItem value="">全部支付</MenuItem>
                <MenuItem value="NO_PAY">NO_PAY</MenuItem>
                <MenuItem value="SUCCESS">SUCCESS</MenuItem>
                <MenuItem value="FAIL">FAIL</MenuItem>
                <MenuItem value="APPLY_REFUND">APPLY_REFUND</MenuItem>
                <MenuItem value="REFUND">REFUND</MenuItem>
              </Select>
              <Select
                size="small"
                value={isChargeFilter}
                onChange={(e) => setIsChargeFilter(e.target.value)}
                displayEmpty
              >
                <MenuItem value="">全部清帳狀態</MenuItem>
                <MenuItem value="true">已清帳</MenuItem>
                <MenuItem value="false">未清帳</MenuItem>
              </Select>
              <DatePicker
                selected={beginDate}
                onChange={(date) => setBeginDate(date)}
                dateFormat="yyyy-MM-dd"
                placeholderText="開始日期"
                className="your-custom-class"
              />

              <DatePicker
                selected={endDate}
                onChange={(date) => setEndDate(date)}
                dateFormat="yyyy-MM-dd"
                placeholderText="結束日期"
                className="your-custom-class"
              />
              <Button variant="contained" onClick={handleSearch}>
                查詢
              </Button>
            </Stack>
          </Box>

          {/* 訂單列表 */}
          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>訂單ID</TableCell>
                  <TableCell>建立時間</TableCell>
                  <TableCell>標籤</TableCell>
                  <TableCell>風格</TableCell>
                  <TableCell>下單用戶名稱</TableCell>
                  <TableCell>下單用戶ID</TableCell>
                  <TableCell>接單用戶名稱</TableCell>
                  <TableCell>接單用戶ID</TableCell>
                  <TableCell>接單者酬勞</TableCell>
                  <TableCell>訂單狀態(purchaseType)</TableCell>
                  <TableCell>付款狀態(payType)</TableCell>
                  <TableCell>是否清帳</TableCell>
                  <TableCell>操作</TableCell>
                  <TableCell>金額</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {orderList.map((item) => (
                  <TableRow key={item.id}>
                    <TableCell>{item.id}</TableCell>
                    <TableCell>{item.create_time}</TableCell>
                    <TableCell>{item.label}</TableCell>
                    <TableCell>{item.style}</TableCell>
                    <TableCell>{item.user_name}</TableCell>
                    <TableCell>{item.user_id}</TableCell>
                    <TableCell>{item.photographer_user_name}</TableCell>
                    <TableCell>{item.photographer_id}</TableCell>
                    <TableCell>{item.photographer_commission}</TableCell>
                    <TableCell>{item.purchase_type}</TableCell>
                    <TableCell>{item.pay_type}</TableCell>
                    <TableCell>
                      {item.purchase_type === "SUCCESS" ?
                        <Switch
                          checked={item.is_charge}
                          onChange={(e) => handleToggleIsCharge(item.id, e.target.checked)}
                          color="primary"
                        /> : "尚未完成"}

                    </TableCell>
                    <TableCell>
                      <Button
                        size="small"
                        variant={item.purchase_type === "SUCCESS" ? "outlined" : "contained"}
                        color="error"
                        disabled={forcingPurchaseId === item.id || item.purchase_type === "SUCCESS"}
                        onClick={() => handleForcePurchaseSuccess(item.id)}
                      >
                        {forcingPurchaseId === item.id
                          ? "處理中..."
                          : item.purchase_type === "SUCCESS"
                            ? "已結單"
                            : "強制結單"}
                      </Button>
                    </TableCell>
                    <TableCell>{item.total_amount}</TableCell>
                  </TableRow>
                ))}
                {orderList.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={14} align="center">
                      目前沒有訂單資料
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>

          {/* 分頁器 */}
          <TablePagination
            component="div"
            count={totalCount}
            page={page}
            onPageChange={handleChangePage}
            rowsPerPage={limit}
            onRowsPerPageChange={handleChangeRowsPerPage}
          />
        </Paper>
      </Container>

      {/* Snackbar */}
      <Snackbar
        open={snackbarOpen}
        autoHideDuration={3000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: "top", horizontal: "center" }}
      >
        <Alert severity={snackbarSeverity} onClose={handleCloseSnackbar} sx={{ width: "100%" }}>
          {snackbarMsg}
        </Alert>
      </Snackbar>
    </>
  );
};

export default OrderManagement;
