import React, { useEffect, useState } from "react";
import {
  // 標籤 API：用於取得所有標籤，供攝影師詳情裡的多選
  fetchGroupsAndLabels,
} from "../../../../src/api/Label";
import {
  addMemberCoins,
  fetchMemberCoinLogs,
  // 會員 / 攝影師 相關 API
  fetchMemberList,
  fetchMemberPurchase,
  fetchPhotographerVerifyList,
  reduceMemberCoins,
  updateMemberVerifyInfo,
  updatePhotographerAcceptOrder,
  updatePhotographerData,
  updatePhotographerLabels,
  updatePhotographerVerifyStatus,
  verifyMemberReal,
} from "../../../../src/api/User";

import Header from "../../../components/AdminHeader";
import LeftBar from "../../../components/AdminLeftBar";

// MUI
import {
  Alert,
  Box,
  Button,
  Chip,
  Container,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Checkbox,
  FormControl,
  FormControlLabel,
  Grid,
  InputAdornment,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Snackbar,
  Stack,
  Switch,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  Tabs,
  TextField,
  Typography
} from "@mui/material";

// 後端狀態對應中文
const statusMap = {
  PENDING: "審核中",
  APPROVED: "通過",
  REJECTED: "被拒絕",
};

const MemberManagement = () => {
  const [tabValue, setTabValue] = useState(0);

  // ───────────────────────────────────────────
  // Snackbar
  // ───────────────────────────────────────────
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMsg, setSnackbarMsg] = useState("");
  const [snackbarSeverity, setSnackbarSeverity] = useState("success");

  const showSnackbar = (message, severity = "info") => {
    setSnackbarMsg(message);
    setSnackbarSeverity(severity);
    setSnackbarOpen(true);
  };
  const handleCloseSnackbar = () => {
    setSnackbarOpen(false);
  };

  // ───────────────────────────────────────────
  // 一、一般會員
  // ───────────────────────────────────────────
  const [memberPage, setMemberPage] = useState(0);
  const [memberLimit, setMemberLimit] = useState(10);
  const [memberTotalCount, setMemberTotalCount] = useState(0);

  const [memberKeyword, setMemberKeyword] = useState("");
  const [memberList, setMemberList] = useState([]);

  // B 幣配發
  const [openCoinDialog, setOpenCoinDialog] = useState(false);
  const [coinMemberId, setCoinMemberId] = useState(null);
  const [coinAmount, setCoinAmount] = useState(0);

  // 訂單列表
  const [openPurchaseDialog, setOpenPurchaseDialog] = useState(false);
  const [purchaseData, setPurchaseData] = useState([]);
  const [purchaseMemberId, setPurchaseMemberId] = useState(null);

  // 會員詳情
  const [openMemberDetailDialog, setOpenMemberDetailDialog] = useState(false);
  const [memberDetailData, setMemberDetailData] = useState(null);
  const [memberVerifyInfo, setMemberVerifyInfo] = useState({
    phone: "",
    birthday: "",
    id_card: "",
  });
  const [memberVerifyInfoSaving, setMemberVerifyInfoSaving] = useState(false);

  const toDateInputValue = (value) => {
    if (!value) return "";
    if (typeof value !== "string") return "";
    // e.g. "2022-01-01T00:00:00Z" -> "2022-01-01"
    return value.length >= 10 ? value.slice(0, 10) : value;
  };

  // 1.1 取得會員列表
  const getMembers = async () => {
    try {
      const pageIndex = memberPage + 1; // 後端 page 從 1 開始
      const res = await fetchMemberList({
        page: pageIndex,
        limit: memberLimit,
        keyword: memberKeyword,
        order: "asc",
        sort: "id",
      });
      if (res?.success) {
        const records = res.data?.records || [];
        setMemberList(records);

        const pageObj = res.data?.page || {};
        setMemberTotalCount(pageObj.total_count || 0);
      } else {
        showSnackbar("取得會員列表失敗", "error");
      }
    } catch (error) {
      console.error("getMembers error:", error);
      showSnackbar("取得會員列表錯誤", "error");
    }
  };

  // 分頁操作
  const handleChangeMemberPage = (e, newPage) => {
    setMemberPage(newPage);
  };
  const handleChangeMemberRowsPerPage = (e) => {
    setMemberLimit(parseInt(e.target.value, 10));
    setMemberPage(0);
  };

  // 審核會員實名
  const handleVerifyMemberReal = (userId, status) => {
    verifyMemberReal(userId, status)
      .then((res) => {
        if (res?.success) {
          showSnackbar("審核成功", "success");
          getMembers();
        } else {
          showSnackbar("審核失敗", "error");
        }
      })
      .catch((err) => {
        console.error("verifyMemberReal error:", err);
        showSnackbar("審核錯誤", "error");
      });
  };

  // 配發 B 幣
  const [coinAction, setCoinAction] = useState('add'); // 預設是配發

  const handleOpenCoinDialog = (memberId) => {
    setCoinMemberId(memberId);
    setCoinAmount(0);
    setOpenCoinDialog(true);
    setCoinAction('add');
  };
  const handleCloseCoinDialog = () => {
    setOpenCoinDialog(false);
    setCoinMemberId(null);
  };
  const handleAddMemberCoins = () => {
    if (!coinMemberId || coinAmount <= 0) {
      showSnackbar("請輸入正確的 B 幣數量", "warning");
      return;
    }
    addMemberCoins({ user_id: coinMemberId, bigtime_coin: coinAmount })
      .then((res) => {
        if (res?.success) {
          showSnackbar("配發成功", "success");
          handleCloseCoinDialog();
          getMembers();
        } else {
          showSnackbar("配發失敗", "error");
        }
      })
      .catch((err) => {
        console.error("addMemberCoins error:", err);
        showSnackbar("配發錯誤", "error");
      });
  };
  const handleReduceMemberCoins = () => {
    if (!coinMemberId || coinAmount <= 0) {
      showSnackbar("請輸入正確的 B 幣數量", "warning");
      return;
    }
    reduceMemberCoins({ user_id: coinMemberId, bigtime_coin: coinAmount })
      .then((res) => {
        if (res?.success) {
          showSnackbar("扣除成功", "success");
          handleCloseCoinDialog();
          getMembers();
        } else {
          showSnackbar("扣除失敗", "error");
        }
      })
      .catch((err) => {
        console.error("reduceMemberCoins error:", err);
        showSnackbar("配發錯誤", "error");
      });
  };
  const loadMemberPurchase = (memberId) => {
    fetchMemberPurchase({ user_id: memberId, page: 1, limit: 10 })
      .then((res) => {
        if (res?.success) {
          const records = res.data?.records || [];
          setPurchaseData(records);
        } else {
          showSnackbar("取得訂單失敗", "error");
        }
      })
      .catch((err) => {
        console.error("fetchMemberPurchase error:", err);
        showSnackbar("取得訂單錯誤", "error");
      });
  };

  // 查看訂單
  const handleOpenPurchaseDialog = (memberId) => {
    setPurchaseMemberId(memberId);
    setPurchaseData([]);
    setOpenPurchaseDialog(true);
    loadMemberPurchase(memberId);
  };
  const handleClosePurchaseDialog = () => {
    setOpenPurchaseDialog(false);
    setPurchaseMemberId(null);
    setPurchaseData([]);
  };

  // 會員詳情
  const handleOpenMemberDetail = (m) => {
    setMemberDetailData(m);
    setMemberVerifyInfo({
      phone: m?.phone || "",
      birthday: toDateInputValue(m?.birthday),
      id_card: m?.id_card || "",
    });
    setOpenMemberDetailDialog(true);
  };
  const handleCloseMemberDetail = () => {
    setOpenMemberDetailDialog(false);
    setMemberDetailData(null);
    setMemberVerifyInfo({ phone: "", birthday: "", id_card: "" });
  };

  const handleSaveMemberVerifyInfo = async () => {
    if (!memberDetailData?.id) return;
    setMemberVerifyInfoSaving(true);
    try {
      const payload = {
        phone: memberVerifyInfo.phone || "",
        birthday: memberVerifyInfo.birthday || "",
        id_card: memberVerifyInfo.id_card || "",
      };
      const res = await updateMemberVerifyInfo(memberDetailData.id, payload);
      if (res?.success) {
        showSnackbar("更新實名認證資訊成功", "success");
        setMemberDetailData((prev) => (prev ? { ...prev, ...payload } : prev));
        getMembers();
      } else {
        showSnackbar("更新實名認證資訊失敗", "error");
      }
    } catch (error) {
      console.error("updateMemberVerifyInfo error:", error);
      showSnackbar("更新實名認證資訊錯誤", "error");
    } finally {
      setMemberVerifyInfoSaving(false);
    }
  };

  // 搜尋會員
  const handleSearchMembers = () => {
    setMemberPage(0);
    getMembers();
  };

  // ───────────────────────────────────────────
  // 二、攝影師
  // ───────────────────────────────────────────
  const [photographerPage, setPhotographerPage] = useState(0);
  const [photographerLimit, setPhotographerLimit] = useState(10);
  const [photographerTotalCount, setPhotographerTotalCount] = useState(0);

  const [photographerKeyword, setPhotographerKeyword] = useState("");
  const [photographerList, setPhotographerList] = useState([]);

  // 攝影師詳情
  const [openPhotographerDetailDialog, setOpenPhotographerDetailDialog] = useState(false);
  const [photographerDetailData, setPhotographerDetailData] = useState(null);
  const [photographerVerifyInfo, setPhotographerVerifyInfo] = useState({
    phone: "",
    birthday: "",
    id_card: "",
  });
  const [photographerVerifyInfoSaving, setPhotographerVerifyInfoSaving] = useState(false);

  // 從標籤API取回的所有標籤
  const [allLabels, setAllLabels] = useState([]);
  // 在攝影師詳情中要更新的值
  const [selectedLabelIds, setSelectedLabelIds] = useState([]);
  const [workUrl, setWorkUrl] = useState("");
  const [photoUrl, setPhotoUrl] = useState("");
  const [serviceLocations, setServiceLocations] = useState([]);

  // 2.1 取得攝影師列表
  const getPhotographers = async () => {
    try {
      const pageIndex = photographerPage + 1;
      const res = await fetchPhotographerVerifyList({
        page: pageIndex,
        limit: photographerLimit,
        keyword: photographerKeyword,
        order: "asc",
        sort: "id",
      });
      if (res?.success) {
        const records = res.data?.records || [];
        setPhotographerList(records);

        const pageObj = res.data?.page || {};
        setPhotographerTotalCount(pageObj.total_count || 0);
      } else {
        showSnackbar("取得攝影師列表失敗", "error");
      }
    } catch (error) {
      console.error("getPhotographers error:", error);
      showSnackbar("取得攝影師列表錯誤", "error");
    }
  };

  // 攝影師分頁
  const handleChangePhotographerPage = (e, newPage) => {
    setPhotographerPage(newPage);
  };
  const handleChangePhotographerRowsPerPage = (e) => {
    setPhotographerLimit(parseInt(e.target.value, 10));
    setPhotographerPage(0);
  };

  // 審核攝影師
  const handleUpdatePhotographerStatus = (user_id, status) => {
    updatePhotographerVerifyStatus({ user_id, status })
      .then((res) => {
        if (res?.success) {
          showSnackbar("審核攝影師成功", "success");
          getPhotographers();
        } else {
          showSnackbar("審核攝影師失敗", "error");
        }
      })
      .catch((err) => {
        console.error("handleUpdatePhotographerStatus error:", err);
        showSnackbar("審核攝影師錯誤", "error");
      });
  };

  // 打開攝影師詳情 (預先帶入作品url/相簿url與標籤)
  const handleOpenPhotographerDetail = (ph) => {
    setPhotographerDetailData(ph);

    setPhotographerVerifyInfo({
      phone: ph?.phone || "",
      birthday: toDateInputValue(ph?.birthday),
      id_card: ph?.id_card || ph?.national_id || "",
    });

    // 預先帶入
    setWorkUrl(ph.work_url || "");
    setPhotoUrl(ph.photo_url || "");
    const sourceLocations =
      ph.addr_responses || ph.addr_requests || ph.addr_requests || ph.addrResponses || [];
    setServiceLocations(
      sourceLocations.map((addr) => ({
        addr: addr?.addr || "",
        lat: addr?.lat ?? "",
        lng: addr?.lng ?? "",
      }))
    );

    // 預先勾選標籤
    const currentLabels = ph.label_responses || [];
    const labelIds = currentLabels.map((lb) => String(lb.label_id));
    setSelectedLabelIds(labelIds);

    setOpenPhotographerDetailDialog(true);
  };
  const handleClosePhotographerDetail = () => {
    setOpenPhotographerDetailDialog(false);
    setPhotographerDetailData(null);
    setPhotographerVerifyInfo({ phone: "", birthday: "", id_card: "" });
    setWorkUrl("");
    setPhotoUrl("");
    setServiceLocations([]);
    setSelectedLabelIds([]);
  };

  const handleChangeServiceLocationCoord = (index, key, value) => {
    setServiceLocations((prev) =>
      prev.map((item, idx) => (idx === index ? { ...item, [key]: value } : item))
    );
  };
  const handleAddServiceLocation = () => {
    setServiceLocations((prev) => [...prev, { addr: "", lat: "", lng: "" }]);
  };
  const handleRemoveServiceLocation = (index) => {
    setServiceLocations((prev) => prev.filter((_, idx) => idx !== index));
  };

  const handleSavePhotographerVerifyInfo = async () => {
    if (!photographerDetailData?.id) return;
    setPhotographerVerifyInfoSaving(true);
    try {
      const payload = {
        phone: photographerVerifyInfo.phone || "",
        birthday: photographerVerifyInfo.birthday || "",
        id_card: photographerVerifyInfo.id_card || "",
      };
      const res = await updateMemberVerifyInfo(photographerDetailData.id, payload);
      if (res?.success) {
        showSnackbar("更新實名認證資訊成功", "success");
        setPhotographerDetailData((prev) => (prev ? { ...prev, ...payload } : prev));
        getPhotographers();
      } else {
        showSnackbar("更新實名認證資訊失敗", "error");
      }
    } catch (error) {
      console.error("updateMemberVerifyInfo error:", error);
      showSnackbar("更新實名認證資訊錯誤", "error");
    } finally {
      setPhotographerVerifyInfoSaving(false);
    }
  };

  const toggleSelectedLabelId = (labelId) => {
    const nextId = String(labelId);
    setSelectedLabelIds((prev) => {
      const exists = prev.some((id) => String(id) === nextId);
      if (exists) return prev.filter((id) => String(id) !== nextId);
      return [...prev, nextId];
    });
  };

  // 同時更新標籤與作品
  const handleUpdatePhotographerAll = async () => {
    try {
      if (!photographerDetailData) return;
      const userId = photographerDetailData.id;

      // 避免後端回傳 "expertLabelIds 不得空白"
      if (selectedLabelIds.length === 0) {
        showSnackbar("請至少選擇一個標籤", "warning");
        return;
      }

      // 1) 更新標籤
      const labelString = selectedLabelIds.join(",");
      const resLabel = await updatePhotographerLabels(userId, { expert_label_ids: labelString });
      if (!resLabel?.success) {
        showSnackbar("更新標籤失敗", "error");
        return;
      }

      // 2) 更新作品
      const normalizedServiceLocations = serviceLocations.map((addr) => {
        const lat = addr?.lat === "" || addr?.lat === null || addr?.lat === undefined
          ? null
          : Number(addr.lat);
        const lng = addr?.lng === "" || addr?.lng === null || addr?.lng === undefined
          ? null
          : Number(addr.lng);
        return {
          addr: String(addr?.addr || "").trim(),
          lat: Number.isNaN(lat) ? null : lat,
          lng: Number.isNaN(lng) ? null : lng,
        };
      }).filter((addr) => addr.addr || addr.lat !== null || addr.lng !== null);

      const resPhoto = await updatePhotographerData(userId, {
        work_url: workUrl,
        photo_url: photoUrl,
        addr_requests: normalizedServiceLocations,
      });
      if (!resPhoto?.success) {
        showSnackbar("更新作品資料失敗", "error");
        return;
      }

      showSnackbar("更新成功", "success");
      handleClosePhotographerDetail();
      getPhotographers();
    } catch (error) {
      console.error("handleUpdatePhotographerAll error:", error);
      showSnackbar("更新失敗", "error");
    }
  };

  // 搜尋攝影師
  const handleSearchPhotographers = () => {
    setPhotographerPage(0);
    getPhotographers();
  };

  // ───────────────────────────────────────────
  // 載入所有標籤
  // ───────────────────────────────────────────
  const getAllLabels = async () => {
    try {
      const res = await fetchGroupsAndLabels();
      if (res?.success) {
        const groupArray = res.data || [];
        const arr = [];
        groupArray.forEach((g) => {
          (g.label_responses || []).forEach((lb) => {
            arr.push({
              label_id: lb.label_id,
              label_name: lb.label,
              group_id: g.group_id,
              group_name: g.group,
              is_flat: lb.is_flat,
              is_dynamic: lb.is_dynamic,
            });
          });
        });
        setAllLabels(arr);
      }
    } catch (error) {
      console.error("getAllLabels error:", error);
    }
  };

  // ───────────────────────────────────────────
  // useEffect
  // ───────────────────────────────────────────
  useEffect(() => {
    // 一開始就抓所有標籤 (供攝影師詳情使用)
    getAllLabels();
  }, []);

  // 如果在「一般會員」分頁，page/limit 改變就抓會員
  useEffect(() => {
    if (tabValue === 0) {
      getMembers();
    }
  }, [tabValue, memberPage, memberLimit]);

  // 如果在「攝影師」分頁，page/limit 改變就抓攝影師
  useEffect(() => {
    if (tabValue === 1) {
      getPhotographers();
    }
  }, [tabValue, photographerPage, photographerLimit]);

  // ───────────────────────────────────────────
  // Render
  // ───────────────────────────────────────────
  const handleChangeTab = (e, newVal) => {
    setTabValue(newVal);
  };
  const [openCoinLogDialog, setOpenCoinLogDialog] = useState(false);
  const [coinLogMemberId, setCoinLogMemberId] = useState(null);
  const [coinLogList, setCoinLogList] = useState([]);
  const [coinLogPage, setCoinLogPage] = useState(0);
  const [coinLogLimit, setCoinLogLimit] = useState(10);
  const [coinLogTotalCount, setCoinLogTotalCount] = useState(0);

  const handleOpenCoinLogDialog = (userId) => {
    setCoinLogMemberId(userId);
    setOpenCoinLogDialog(true);
    fetchMemberCoinLogs({
      user_id: userId,
      page: 1,
      limit: coinLogLimit,
      order: "desc",
      sort: "id",
    })
      .then((res) => {
        if (res?.success) {
          setCoinLogList(res.data.records);
          setCoinLogPage((res.data.page.current_page || 1) - 1);
          setCoinLogTotalCount(res.data.page.total_count || 0);
        } else {
          showSnackbar("取得 B 幣紀錄失敗", "error");
        }
      })
      .catch((err) => {
        console.error("fetchMemberCoinLogs error:", err);
        showSnackbar("取得 B 幣紀錄錯誤", "error");
      });
  };
  const handleChangeCoinLogPage = (event, newPage) => {
    const pageIndex = newPage + 1; // 後端從 1 開始

    fetchMemberCoinLogs({
      user_id: coinLogMemberId,
      page: pageIndex,
      limit: coinLogLimit,
      order: "desc",
      sort: "id",
    })
      .then((res) => {
        if (res?.success) {
          setCoinLogList(res.data.records);
          setCoinLogPage(newPage); // 注意：這裡是 newPage，不用再 -1
          setCoinLogTotalCount(res.data.page.total_count || 0);
        } else {
          showSnackbar("取得 B 幣紀錄失敗", "error");
        }
      })
      .catch((err) => {
        console.error("fetchMemberCoinLogs error:", err);
        showSnackbar("取得 B 幣紀錄錯誤", "error");
      });
  };


  const handleChangeCoinLogRowsPerPage = (event) => {
    const newLimit = parseInt(event.target.value, 10);
    setCoinLogLimit(newLimit);
    setCoinLogPage(0);

    fetchMemberCoinLogs({
      user_id: coinLogMemberId,
      page: 1,
      limit: newLimit,
      order: "desc",
      sort: "id",
    })
      .then((res) => {
        if (res?.success) {
          setCoinLogList(res.data.records);
          setCoinLogPage(0);
          setCoinLogTotalCount(res.data.page.total_count || 0);
        } else {
          showSnackbar("取得 B 幣紀錄失敗", "error");
        }
      })
      .catch((err) => {
        console.error("fetchMemberCoinLogs error:", err);
        showSnackbar("取得 B 幣紀錄錯誤", "error");
      });
  };

  const handleCloseCoinLogDialog = () => {
    setOpenCoinLogDialog(false);
    setCoinLogList([]);
    setCoinLogMemberId(null);
  };
  const handleToggleAcceptOrder = (userId, isAccept) => {
    updatePhotographerAcceptOrder(userId, isAccept)
      .then((res) => {
        if (res?.success) {
          showSnackbar("接單狀態已更新", "success");
          getPhotographers(); // 重新取得列表，刷新開關狀態
        } else {
          showSnackbar("更新失敗", "error");
        }
      })
      .catch((err) => {
        console.error("updatePhotographerAcceptOrder error:", err);
        showSnackbar("更新錯誤", "error");
      });
  };

  const staticLabels = allLabels.filter(
    (l) => l?.is_flat === true || String(l?.group_name || "").includes("靜態")
  );
  const dynamicLabels = allLabels.filter(
    (l) => l?.is_dynamic === true || String(l?.group_name || "").includes("動態")
  );
  const groupedLabelIds = new Set(
    [...staticLabels, ...dynamicLabels].map((l) => String(l?.label_id))
  );
  const otherLabels = allLabels.filter((l) => !groupedLabelIds.has(String(l?.label_id)));
  return (
    <>
      <Header />
      <LeftBar />
      <Container maxWidth="lg" sx={{ pt: 10, pb: 4 }}>
        <Paper sx={{ p: 2, mb: 4 }}>
          <Typography variant="h4" sx={{ mb: 2, fontWeight: 600 }}>
            會員管理
          </Typography>
          <Tabs value={tabValue} onChange={handleChangeTab} sx={{ mb: 3 }}>
            <Tab label="一般會員" />
            <Tab label="攝影師" />
          </Tabs>

          {/* ─────────────────────────────────────────────────────────────
              一般會員
             ───────────────────────────────────────────────────────────── */}
          {tabValue === 0 && (
            <Paper sx={{ p: 2 }}>
              {/* 搜尋 */}
              <Box mb={2} display="flex" alignItems="center" gap={2}>
                <TextField
                  size="small"
                  placeholder="搜尋關鍵字"
                  value={memberKeyword}
                  onChange={(e) => setMemberKeyword(e.target.value)}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                      </InputAdornment>
                    ),
                  }}
                />
                <Button variant="contained" onClick={handleSearchMembers}>
                  搜尋
                </Button>
              </Box>

              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>會員ID</TableCell>
                      <TableCell>姓名</TableCell>
                      <TableCell>電話</TableCell>
                      <TableCell>實名狀態</TableCell>

                      <TableCell align="center">操作</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {memberList.map((m) => {
                      const statusLabel = statusMap[m.real_status] || m.real_status;
                      return (
                        <TableRow key={m.id}>
                          <TableCell>{m.id}</TableCell>
                          <TableCell>{m.name}</TableCell>
                          <TableCell>{m.phone}</TableCell>
                          <TableCell>{statusLabel}</TableCell>
                          <TableCell align="center">
                            <Stack direction="row" spacing={1} justifyContent="center">
                              {/* 詳情 */}
                              <Button variant="outlined" onClick={() => handleOpenMemberDetail(m)}>
                                詳情
                              </Button>
                              {/* 審核 (僅 PENDING) */}
                              {m.real_status === "PENDING" && (
                                <>
                                  <Button
                                    variant="outlined"
                                    onClick={() => handleVerifyMemberReal(m.id, "APPROVED")}
                                  >
                                    通過
                                  </Button>
                                  <Button
                                    variant="outlined"
                                    color="warning"
                                    onClick={() => handleVerifyMemberReal(m.id, "REJECTED")}
                                  >
                                    駁回
                                  </Button>
                                </>
                              )}
                              {/* 配發 B 幣 */}
                              <Button variant="contained" onClick={() => handleOpenCoinDialog(m.id)}>
                                配發B幣
                              </Button>
                              {/* 查看訂單 */}
                              <Button variant="outlined" onClick={() => handleOpenPurchaseDialog(m.id)}>
                                訂單
                              </Button>
                              <Button variant="outlined" onClick={() => handleOpenCoinLogDialog(m.id)}>
                                B幣紀錄
                              </Button>
                            </Stack>
                          </TableCell>
                        </TableRow>
                      );
                    })}
                    {memberList.length === 0 && (
                      <TableRow>
                        <TableCell colSpan={5} align="center">
                          目前沒有會員資料
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </TableContainer>

              <TablePagination
                component="div"
                count={memberTotalCount}
                page={memberPage}
                onPageChange={handleChangeMemberPage}
                rowsPerPage={memberLimit}
                onRowsPerPageChange={handleChangeMemberRowsPerPage}
              />
            </Paper>
          )}

          {/* ─────────────────────────────────────────────────────────────
              攝影師
             ───────────────────────────────────────────────────────────── */}
          {tabValue === 1 && (
            <Paper sx={{ p: 2 }}>
              <Box mb={2} display="flex" alignItems="center" gap={2}>
                <TextField
                  size="small"
                  placeholder="搜尋關鍵字"
                  value={photographerKeyword}
                  onChange={(e) => setPhotographerKeyword(e.target.value)}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                      </InputAdornment>
                    ),
                  }}
                />
                <Button variant="contained" onClick={handleSearchPhotographers}>
                  搜尋
                </Button>
              </Box>

              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>攝影師ID</TableCell>
                      <TableCell>姓名</TableCell>
                      <TableCell>電話</TableCell>
                      <TableCell>審核狀態</TableCell>
                      <TableCell>審核權限</TableCell>
                      <TableCell align="center">操作</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {photographerList.map((ph) => {
                      const statusLabel = statusMap[ph.status] || ph.status;
                      const fullName = `${ph.firstname || ""}${ph.lastname || ""}`;
                      return (
                        <TableRow key={ph.id}>
                          <TableCell>{ph.id}</TableCell>
                          <TableCell>{fullName}</TableCell>
                          <TableCell>{ph.phone}</TableCell>
                          <TableCell>{statusLabel}</TableCell>
                          <TableCell>
                            <FormControlLabel
                              control={
                                <Switch
                                  checked={ph.is_accept_order_back}
                                  onChange={(e) => handleToggleAcceptOrder(ph.id, e.target.checked)}
                                />
                              }
                              label="接單"
                            /></TableCell>
                          <TableCell align="center">
                            <Stack direction="row" spacing={1} justifyContent="center">
                              {/* 詳情 */}
                              <Button
                                variant="outlined"
                                onClick={() => handleOpenPhotographerDetail(ph)}
                              >
                                詳情
                              </Button>
                              {/* 審核 (僅 PENDING) */}
                              {ph.status === "PENDING" && (
                                <>
                                  <Button
                                    variant="outlined"
                                    onClick={() => handleUpdatePhotographerStatus(ph.id, "APPROVED")}
                                  >
                                    通過
                                  </Button>
                                  <Button
                                    variant="outlined"
                                    color="warning"
                                    onClick={() => handleUpdatePhotographerStatus(ph.id, "REJECTED")}
                                  >
                                    駁回
                                  </Button>
                                </>
                              )}
                            </Stack>
                          </TableCell>
                        </TableRow>
                      );
                    })}
                    {photographerList.length === 0 && (
                      <TableRow>
                        <TableCell colSpan={5} align="center">
                          目前沒有攝影師資料
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </TableContainer>

              <TablePagination
                component="div"
                count={photographerTotalCount}
                page={photographerPage}
                onPageChange={handleChangePhotographerPage}
                rowsPerPage={photographerLimit}
                onRowsPerPageChange={handleChangePhotographerRowsPerPage}
              />
            </Paper>
          )}

          {/* ──────────────────────────────────────────
            以下為各種 Dialog
           ────────────────────────────────────────── */}

          {/* 配發 / 扣除 B 幣 */}
          <Dialog open={openCoinDialog} onClose={handleCloseCoinDialog} fullWidth>
            <DialogTitle>B 幣操作</DialogTitle>
            <DialogContent dividers>
              <Typography>會員ID: {coinMemberId}</Typography>

              {/* 選擇操作模式 */}
              <FormControl fullWidth sx={{ mt: 2 }}>
                <InputLabel>操作方式</InputLabel>
                <Select
                  value={coinAction}
                  label="操作方式"
                  onChange={(e) => setCoinAction(e.target.value)}
                >
                  <MenuItem value="add">配發</MenuItem>
                  <MenuItem value="reduce">扣除</MenuItem>
                </Select>
              </FormControl>

              {/* 輸入金額 */}
              <TextField
                fullWidth
                sx={{ mt: 2 }}
                type="number"
                label="B 幣數量"
                value={coinAmount}
                onChange={(e) => setCoinAmount(e.target.value)}
              />
            </DialogContent>
            <DialogActions>
              <Button onClick={handleCloseCoinDialog}>取消</Button>
              <Button
                variant="contained"
                color={coinAction === 'reduce' ? 'error' : 'primary'}
                onClick={
                  coinAction === 'reduce' ? handleReduceMemberCoins : handleAddMemberCoins
                }
              >
                確定
              </Button>
            </DialogActions>
          </Dialog>

          {/* 訂單列表 */}
          <Dialog open={openPurchaseDialog} onClose={handleClosePurchaseDialog} fullWidth>
            <DialogTitle>訂單列表 (會員ID: {purchaseMemberId})</DialogTitle>
            <DialogContent dividers>
              {purchaseData.length === 0 ? (
                <Typography>暫無訂單資料</Typography>
              ) : (
                <TableContainer>
                  <Table>
                    <TableHead>
                      <TableRow>
                        <TableCell>訂單ID</TableCell>
                        <TableCell>建立時間</TableCell>
                        <TableCell>標籤</TableCell>
                        <TableCell>金額</TableCell>
                        <TableCell>支付狀態</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {purchaseData.map((order) => (
                        <TableRow key={order.id}>
                          <TableCell>{order.id}</TableCell>
                          <TableCell>{order.create_time}</TableCell>
                          <TableCell>{order.label}</TableCell>
                          <TableCell>{order.total_amount}</TableCell>
                          <TableCell>{order.payment_response?.status}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
              )}
            </DialogContent>
            <DialogActions>
              <Button onClick={handleClosePurchaseDialog}>關閉</Button>
            </DialogActions>
          </Dialog>
          <Dialog open={openCoinLogDialog} onClose={handleCloseCoinLogDialog} fullWidth maxWidth="md">
            <DialogTitle>B 幣紀錄 (會員ID: {coinLogMemberId})</DialogTitle>
            <DialogContent dividers>
              {coinLogList.length === 0 ? (
                <Typography>暫無紀錄</Typography>
              ) : (
                <>
                  <TableContainer>
                    <Table>
                      <TableHead>
                        <TableRow>
                          <TableCell>ID</TableCell>
                          <TableCell>建立時間</TableCell>
                          <TableCell>B 幣數量</TableCell>
                          <TableCell>備註</TableCell>
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {coinLogList.map((log) => (
                          <TableRow key={log.id}>
                            <TableCell>{log.id}</TableCell>
                            <TableCell>{log.create_time}</TableCell>
                            <TableCell>{log.bigtime_coin}</TableCell>
                            <TableCell>{log.remark}</TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </TableContainer>

                  {/* 🔽 分頁元件 */}
                  <TablePagination
                    component="div"
                    count={coinLogTotalCount}
                    page={coinLogPage}
                    rowsPerPage={coinLogLimit}
                    onPageChange={handleChangeCoinLogPage}
                    onRowsPerPageChange={handleChangeCoinLogRowsPerPage}
                  />


                </>
              )}
            </DialogContent>

            <DialogActions>
              <Button onClick={handleCloseCoinLogDialog}>關閉</Button>
            </DialogActions>
          </Dialog>

          {/* 一般會員詳情 */}
          <Dialog open={openMemberDetailDialog} onClose={handleCloseMemberDetail} fullWidth maxWidth="md">
            <DialogTitle sx={{ pb: 1 }}>
              <Stack direction="row" alignItems="center" justifyContent="space-between" spacing={2}>
                <Typography variant="h6" sx={{ fontWeight: 700 }}>
                  會員詳情
                </Typography>
                {memberDetailData?.real_status && (
                  <Chip
                    size="small"
                    label={statusMap[memberDetailData.real_status] || memberDetailData.real_status}
                    color={
                      memberDetailData.real_status === "APPROVED"
                        ? "success"
                        : memberDetailData.real_status === "REJECTED"
                          ? "error"
                          : "warning"
                    }
                    variant="outlined"
                  />
                )}
              </Stack>
            </DialogTitle>
            <DialogContent dividers sx={{ bgcolor: "grey.50" }}>
              {memberDetailData ? (
                <Stack spacing={2.5}>
                  <Paper variant="outlined" sx={{ p: 2 }}>
                    <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
                      基本資料
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={6}>
                        <Stack spacing={1}>
                          <Typography>會員ID：{memberDetailData.id}</Typography>
                          <Typography>姓名：{memberDetailData.name}</Typography>
                          <Typography>Email：{memberDetailData.email || "—"}</Typography>
                          <Typography>B 幣金額：{memberDetailData.bigtime_coin}</Typography>
                        </Stack>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Stack spacing={2}>
                          <TextField
                            fullWidth
                            label="電話"
                            value={memberVerifyInfo.phone}
                            onChange={(e) =>
                              setMemberVerifyInfo((prev) => ({ ...prev, phone: e.target.value }))
                            }
                          />
                          <TextField
                            fullWidth
                            type="date"
                            label="生日"
                            value={memberVerifyInfo.birthday}
                            onChange={(e) =>
                              setMemberVerifyInfo((prev) => ({ ...prev, birthday: e.target.value }))
                            }
                            InputLabelProps={{ shrink: true }}
                          />
                          <TextField
                            fullWidth
                            label="身分證字號"
                            value={memberVerifyInfo.id_card}
                            onChange={(e) =>
                              setMemberVerifyInfo((prev) => ({ ...prev, id_card: e.target.value }))
                            }
                          />
                        </Stack>
                      </Grid>
                    </Grid>
                  </Paper>

                  {(memberDetailData.file_id_front_url || memberDetailData.file_id_back_url) && (
                    <Paper variant="outlined" sx={{ p: 2 }}>
                      <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
                        證件照片
                      </Typography>
                      <Grid container spacing={2}>
                        {memberDetailData.file_id_front_url && (
                          <Grid item xs={12} sm={6}>
                            <Typography variant="body2" sx={{ mb: 1, color: "text.secondary" }}>
                              正面
                            </Typography>
                            <Box
                              component="img"
                              src={memberDetailData.file_id_front_url}
                              alt="front"
                              sx={{
                                width: "100%",
                                maxHeight: 260,
                                objectFit: "contain",
                                borderRadius: 2,
                                border: "1px solid",
                                borderColor: "divider",
                                bgcolor: "common.white",
                              }}
                            />
                          </Grid>
                        )}
                        {memberDetailData.file_id_back_url && (
                          <Grid item xs={12} sm={6}>
                            <Typography variant="body2" sx={{ mb: 1, color: "text.secondary" }}>
                              背面
                            </Typography>
                            <Box
                              component="img"
                              src={memberDetailData.file_id_back_url}
                              alt="back"
                              sx={{
                                width: "100%",
                                maxHeight: 260,
                                objectFit: "contain",
                                borderRadius: 2,
                                border: "1px solid",
                                borderColor: "divider",
                                bgcolor: "common.white",
                              }}
                            />
                          </Grid>
                        )}
                      </Grid>
                    </Paper>
                  )}

                  {memberDetailData.photo_response && (
                    <Paper variant="outlined" sx={{ p: 2 }}>
                      <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
                        攝影師資料
                      </Typography>
                      <Grid container spacing={2}>
                        <Grid item xs={12} sm={6}>
                          <TextField
                            fullWidth
                            label="作品連結"
                            value={memberDetailData.photo_response.work_url || ""}
                            InputProps={{ readOnly: true }}
                          />
                          {memberDetailData.photo_response.work_url && (
                            <Box
                              component="img"
                              src={memberDetailData.photo_response.work_url}
                              alt="work"
                              sx={{
                                mt: 1,
                                width: "100%",
                                maxHeight: 260,
                                objectFit: "contain",
                                borderRadius: 2,
                                border: "1px solid",
                                borderColor: "divider",
                                bgcolor: "common.white",
                              }}
                            />
                          )}
                        </Grid>
                        <Grid item xs={12} sm={6}>
                          <TextField
                            fullWidth
                            label="相簿連結"
                            value={memberDetailData.photo_response.photo_url || ""}
                            InputProps={{ readOnly: true }}
                          />
                          {memberDetailData.photo_response.photo_url && (
                            <Box
                              component="img"
                              src={memberDetailData.photo_response.photo_url}
                              alt="photo"
                              sx={{
                                mt: 1,
                                width: "100%",
                                maxHeight: 260,
                                objectFit: "contain",
                                borderRadius: 2,
                                border: "1px solid",
                                borderColor: "divider",
                                bgcolor: "common.white",
                              }}
                            />
                          )}
                        </Grid>
                        {memberDetailData.label_responses?.length > 0 && (
                          <Grid item xs={12}>
                            <Typography sx={{ color: "text.secondary" }}>
                              標籤：{memberDetailData.label_responses.map((lb) => lb.label).join("、")}
                            </Typography>
                          </Grid>
                        )}
                      </Grid>
                    </Paper>
                  )}
                </Stack>
              ) : (
                <Typography color="text.secondary">無資料</Typography>
              )}
            </DialogContent>
            <DialogActions sx={{ px: 3, py: 2 }}>
              <Button onClick={handleCloseMemberDetail}>關閉</Button>
              <Button
                variant="contained"
                onClick={handleSaveMemberVerifyInfo}
                disabled={!memberDetailData || memberVerifyInfoSaving}
              >
                儲存實名資訊
              </Button>
            </DialogActions>
          </Dialog>

          {/* 攝影師詳情 (可同時更新作品URL, 相簿URL, 標籤) */}
          <Dialog
            open={openPhotographerDetailDialog}
            onClose={handleClosePhotographerDetail}
            fullWidth
            maxWidth="md"
          >
            <DialogTitle sx={{ pb: 1 }}>
              <Stack direction="row" alignItems="center" justifyContent="space-between" spacing={2}>
                <Typography variant="h6" sx={{ fontWeight: 700 }}>
                  攝影師詳情
                </Typography>
                {photographerDetailData?.status && (
                  <Chip
                    size="small"
                    label={statusMap[photographerDetailData.status] || photographerDetailData.status}
                    color={
                      photographerDetailData.status === "APPROVED"
                        ? "success"
                        : photographerDetailData.status === "REJECTED"
                          ? "error"
                          : "warning"
                    }
                    variant="outlined"
                  />
                )}
              </Stack>
            </DialogTitle>
            <DialogContent dividers sx={{ bgcolor: "grey.50" }}>
              {photographerDetailData ? (
                <Stack spacing={2.5}>
                  <Paper variant="outlined" sx={{ p: 2 }}>
                    <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
                      基本資訊
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={6}>
                        <Stack spacing={1}>
                          <Typography>攝影師ID：{photographerDetailData.id}</Typography>
                          <Typography>
                            姓名：{photographerDetailData.firstname}
                            {photographerDetailData.lastname}
                          </Typography>
                          <Typography>居住城市：{photographerDetailData.live_city || "—"}</Typography>
                        </Stack>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Stack spacing={2}>
                          <TextField
                            fullWidth
                            label="電話"
                            value={photographerVerifyInfo.phone}
                            onChange={(e) =>
                              setPhotographerVerifyInfo((prev) => ({ ...prev, phone: e.target.value }))
                            }
                          />
                          <TextField
                            fullWidth
                            type="date"
                            label="生日"
                            value={photographerVerifyInfo.birthday}
                            onChange={(e) =>
                              setPhotographerVerifyInfo((prev) => ({
                                ...prev,
                                birthday: e.target.value,
                              }))
                            }
                            InputLabelProps={{ shrink: true }}
                          />
                          <TextField
                            fullWidth
                            label="身分證字號"
                            value={photographerVerifyInfo.id_card}
                            onChange={(e) =>
                              setPhotographerVerifyInfo((prev) => ({ ...prev, id_card: e.target.value }))
                            }
                          />
                        </Stack>
                      </Grid>
                      {photographerDetailData.file_url && (
                        <Grid item xs={12}>
                          <Typography variant="body2" sx={{ mb: 1, color: "text.secondary" }}>
                            身分證照片
                          </Typography>
                          <Box
                            component="img"
                            src={photographerDetailData.file_url}
                            alt="身份證"
                            sx={{
                              width: "100%",
                              maxHeight: 260,
                              objectFit: "contain",
                              borderRadius: 2,
                              border: "1px solid",
                              borderColor: "divider",
                              bgcolor: "common.white",
                            }}
                          />
                        </Grid>
                      )}
                    </Grid>
                  </Paper>

                  {/* 收款方式 */}
                  <Paper variant="outlined" sx={{ p: 2 }}>
                    <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
                      收款方式
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={6}>
                        <Stack spacing={1}>
                          <Typography>收款帳號：{photographerDetailData.bank_account || "未提供"}</Typography>
                          <Typography>帳戶名稱：{photographerDetailData.bank_name || "未提供"}</Typography>
                          <Typography>銀行名稱：{photographerDetailData.bank || "未提供"}</Typography>
                          <Typography>分行名稱：{photographerDetailData.bank_sub || "未提供"}</Typography>
                        </Stack>
                      </Grid>
                      {photographerDetailData.bank_file_url && (
                        <Grid item xs={12} md={6}>
                          <Typography variant="body2" sx={{ mb: 1, color: "text.secondary" }}>
                            銀行存摺照片
                          </Typography>
                          <Box
                            component="img"
                            src={photographerDetailData.bank_file_url}
                            alt="存摺"
                            sx={{
                              width: "100%",
                              maxHeight: 260,
                              objectFit: "contain",
                              borderRadius: 2,
                              border: "1px solid",
                              borderColor: "divider",
                              bgcolor: "common.white",
                            }}
                          />
                        </Grid>
                      )}
                    </Grid>
                  </Paper>

                  {/* 可服務地點 */}
                  <Paper variant="outlined" sx={{ p: 2 }}>
                    <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ mb: 1 }}>
                      <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
                        可服務地點
                      </Typography>
                      <Button size="small" variant="outlined" onClick={handleAddServiceLocation}>
                        新增地點
                      </Button>
                    </Stack>
                    {serviceLocations.length === 0 ? (
                      <Typography color="text.secondary">尚未設定地點，可按右上角新增。</Typography>
                    ) : (
                      <Stack spacing={2}>
                        {serviceLocations.map((addr, idx) => (
                          <Grid container spacing={1.5} key={idx}>
                            <Grid item xs={12} sm={5}>
                              <TextField
                                fullWidth
                                size="small"
                                label="地名 / 地址"
                                value={addr.addr ?? ""}
                                onChange={(e) =>
                                  handleChangeServiceLocationCoord(idx, "addr", e.target.value)
                                }
                              />
                            </Grid>
                            <Grid item xs={6} sm={3}>
                              <TextField
                                fullWidth
                                size="small"
                                type="number"
                                label="Latitude"
                                value={addr.lat ?? ""}
                                onChange={(e) =>
                                  handleChangeServiceLocationCoord(idx, "lat", e.target.value)
                                }
                                inputProps={{ step: "any" }}
                              />
                            </Grid>
                            <Grid item xs={6} sm={3}>
                              <TextField
                                fullWidth
                                size="small"
                                type="number"
                                label="Longitude"
                                value={addr.lng ?? ""}
                                onChange={(e) =>
                                  handleChangeServiceLocationCoord(idx, "lng", e.target.value)
                                }
                                inputProps={{ step: "any" }}
                              />
                            </Grid>
                            <Grid item xs={12} sm={1}>
                              <Button
                                fullWidth
                                color="error"
                                variant="text"
                                onClick={() => handleRemoveServiceLocation(idx)}
                              >
                                刪除
                              </Button>
                            </Grid>
                          </Grid>
                        ))}
                      </Stack>
                    )}
                  </Paper>

                  {/* 標籤多選更新 */}
                  <Box>
                    <Typography variant="h6" gutterBottom>
                      🏷️ 標籤 (可多選更新)
                    </Typography>
                    <Stack spacing={2}>
                      {staticLabels.length > 0 && (
                        <Box>
                          <Typography variant="subtitle2" sx={{ mb: 1, color: "text.secondary" }}>
                            靜態
                          </Typography>
                          <Grid container spacing={1}>
                            {staticLabels.map((al) => (
                              <Grid item xs={12} sm={6} md={4} key={`static-${al.label_id}`}>
                                <FormControlLabel
                                  control={
                                    <Checkbox
                                      checked={selectedLabelIds.includes(String(al.label_id))}
                                      onChange={() => toggleSelectedLabelId(al.label_id)}
                                    />
                                  }
                                  label={`${al.group_name} / ${al.label_name}`}
                                />
                              </Grid>
                            ))}
                          </Grid>
                        </Box>
                      )}

                      {dynamicLabels.length > 0 && (
                        <Box>
                          <Typography variant="subtitle2" sx={{ mb: 1, color: "text.secondary" }}>
                            動態
                          </Typography>
                          <Grid container spacing={1}>
                            {dynamicLabels.map((al) => (
                              <Grid item xs={12} sm={6} md={4} key={`dynamic-${al.label_id}`}>
                                <FormControlLabel
                                  control={
                                    <Checkbox
                                      checked={selectedLabelIds.includes(String(al.label_id))}
                                      onChange={() => toggleSelectedLabelId(al.label_id)}
                                    />
                                  }
                                  label={`${al.group_name} / ${al.label_name}`}
                                />
                              </Grid>
                            ))}
                          </Grid>
                        </Box>
                      )}

                      {(staticLabels.length === 0 && dynamicLabels.length === 0) ||
                      otherLabels.length > 0 ? (
                        <Box>
                          <Typography variant="subtitle2" sx={{ mb: 1, color: "text.secondary" }}>
                            {staticLabels.length === 0 && dynamicLabels.length === 0 ? "標籤" : "其他"}
                          </Typography>
                          <Grid container spacing={1}>
                            {(staticLabels.length === 0 && dynamicLabels.length === 0
                              ? allLabels
                              : otherLabels
                            ).map((al) => (
                              <Grid item xs={12} sm={6} md={4} key={`other-${al.label_id}`}>
                                <FormControlLabel
                                  control={
                                    <Checkbox
                                      checked={selectedLabelIds.includes(String(al.label_id))}
                                      onChange={() => toggleSelectedLabelId(al.label_id)}
                                    />
                                  }
                                  label={`${al.group_name} / ${al.label_name}`}
                                />
                              </Grid>
                            ))}
                          </Grid>
                        </Box>
                      ) : null}
                    </Stack>
                  </Box>

                  {/* 作品/相簿 */}
                  <Paper variant="outlined" sx={{ p: 2 }}>
                    <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
                      作品/相簿 (可更新)
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={6}>
                        <TextField
                          label="作品連結 (work_url)"
                          value={workUrl}
                          onChange={(e) => setWorkUrl(e.target.value)}
                          fullWidth
                        />
                        {workUrl && (
                          <Box
                            component="img"
                            src={workUrl}
                            alt="作品"
                            sx={{
                              mt: 1,
                              width: "100%",
                              maxHeight: 260,
                              objectFit: "contain",
                              borderRadius: 2,
                              border: "1px solid",
                              borderColor: "divider",
                              bgcolor: "common.white",
                            }}
                          />
                        )}
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <TextField
                          label="相簿連結 (photo_url)"
                          value={photoUrl}
                          onChange={(e) => setPhotoUrl(e.target.value)}
                          fullWidth
                        />
                        {photoUrl && (
                          <Box
                            component="img"
                            src={photoUrl}
                            alt="相簿"
                            sx={{
                              mt: 1,
                              width: "100%",
                              maxHeight: 260,
                              objectFit: "contain",
                              borderRadius: 2,
                              border: "1px solid",
                              borderColor: "divider",
                              bgcolor: "common.white",
                            }}
                          />
                        )}
                      </Grid>
                    </Grid>
                  </Paper>
                </Stack>
              ) : (
                <Typography color="text.secondary">無資料</Typography>
              )}
            </DialogContent>

            <DialogActions sx={{ px: 3, py: 2 }}>
              <Button onClick={handleClosePhotographerDetail}>取消</Button>
              <Button
                variant="outlined"
                onClick={handleSavePhotographerVerifyInfo}
                disabled={!photographerDetailData || photographerVerifyInfoSaving}
              >
                儲存實名資訊
              </Button>
              <Button variant="contained" onClick={handleUpdatePhotographerAll}>
                確定修改
              </Button>
            </DialogActions>
          </Dialog>

          {/* Snackbar */}
          <Snackbar
            open={snackbarOpen}
            autoHideDuration={3000}
            onClose={handleCloseSnackbar}
            anchorOrigin={{ vertical: "top", horizontal: "center" }}
          >
            <Alert severity={snackbarSeverity} onClose={handleCloseSnackbar} sx={{ width: "100%" }}>
              {snackbarMsg}
            </Alert>
          </Snackbar>
        </Paper>
      </Container>
    </>
  );
};

export default MemberManagement;
