import { StyledFlexBox } from "../../styles/Shared.styles";
import LoginForm from "./LoginForm";

const Login = () => {
  return (
    <StyledFlexBox
      width={448}
      height={513}
      mx="auto"
      pt={64}
      bg="#fff"
      flexDirection="column"
      alignItems="center"
      mt="calc(50vh - 300px)"
      boxShadow="0px 2px 20px rgba(0, 0, 0, 0.05)"
      borderRadius="16px"
    >
      <StyledFlexBox
        lineHeight="36px"
        fontSize={40}
        color="#004B97"
        fontWeight={800}
      >
        Bigtime
      </StyledFlexBox>
      <LoginForm />
    </StyledFlexBox>
  );
};
export default Login;
