import React, { useEffect, useState } from "react";
import {
  createGroup,
  createLabel,
  createStyle,
  deleteGroup,
  deleteLabel,
  deleteStyle,
  fetchGroupsAndLabels,
  fetchStyles,
  updateGroup,
  updateLabel,
  updateStyle
} from "../../../../src/api/Label"; // ← 路徑依實際情況調整

// MUI
import {
  Alert,
  Box,
  Button,
  Checkbox,
  Container,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControlLabel,
  Grid,
  Paper,
  Snackbar,
  Stack,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Tabs,
  TextField,
  Typography,
} from "@mui/material";
import Header from "../../../components/AdminHeader";
import LeftBar from "../../../components/AdminLeftBar";
const LabelManagement = () => {
  const [tabValue, setTabValue] = useState(0);

  // ──────────────────────────────────────────
  // 全局：Snackbar
  // ──────────────────────────────────────────
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMsg, setSnackbarMsg] = useState("");
  const [snackbarSeverity, setSnackbarSeverity] = useState("success");

  const showSnackbar = (msg, severity = "success") => {
    setSnackbarMsg(msg);
    setSnackbarSeverity(severity);
    setSnackbarOpen(true);
  };
  const handleCloseSnackbar = () => {
    setSnackbarOpen(false);
  };

  // ──────────────────────────────────────────
  // 一、群組管理
  // ──────────────────────────────────────────
  const [groupList, setGroupList] = useState([]);
  const [openGroupDialog, setOpenGroupDialog] = useState(false);
  const [editGroupData, setEditGroupData] = useState(null);
  const [groupName, setGroupName] = useState("");

  // 1.1 取得群組 (from GET /bo/label)
  const fetchGroups = () => {
    fetchGroupsAndLabels()
      .then((res) => {
        if (res?.success) {
          const dataArr = res.data || [];
          // 從 dataArr 裡面只取 group_id, group
          const groups = dataArr.map((g) => ({
            group_id: g.group_id,
            group: g.group,
          }));
          setGroupList(groups);
        } else {
          showSnackbar("取得群組列表失敗", "error");
        }
      })
      .catch((err) => {
        console.error("fetchGroups error", err);
        showSnackbar("取得群組列表發生錯誤", "error");
      });
  };

  // 1.2 建立群組
  const handleCreateGroup = () => {
    if (!groupName.trim()) {
      showSnackbar("請輸入群組名稱", "warning");
      return;
    }
    createGroup({ group_name: groupName })
      .then((res) => {
        if (res?.success) {
          showSnackbar("新增群組成功");
          setGroupName("");
          fetchGroups();
          handleCloseGroupDialog();
        } else {
          showSnackbar("新增群組失敗", "error");
        }
      })
      .catch((err) => {
        console.error("handleCreateGroup error", err);
        showSnackbar("新增群組失敗", "error");
      });
  };

  // 1.3 修改群組
  const handleUpdateGroup = () => {
    if (!editGroupData) return;
    const { group_id } = editGroupData;
    if (!groupName.trim()) {
      showSnackbar("群組名稱不可為空", "warning");
      return;
    }
    updateGroup(group_id, { group_name: groupName })
      .then((res) => {
        if (res?.success) {
          showSnackbar("修改群組成功");
          fetchGroups();
          handleCloseGroupDialog();
        } else {
          showSnackbar("修改群組失敗", "error");
        }
      })
      .catch((err) => {
        console.error("handleUpdateGroup error", err);
        showSnackbar("修改群組失敗", "error");
      });
  };

  // 1.4 刪除群組
  const handleDeleteGroup = (group_id) => {
    if (!window.confirm("確定要刪除此群組嗎？")) return;
    deleteGroup(group_id)
      .then((res) => {
        if (res?.success) {
          showSnackbar("刪除群組成功");
          fetchGroups();
        } else {
          showSnackbar("刪除群組失敗", "error");
        }
      })
      .catch((err) => {
        console.error("handleDeleteGroup error", err);
        showSnackbar("刪除群組失敗", "error");
      });
  };

  const handleOpenGroupDialog = (item) => {
    if (item) {
      setEditGroupData(item);
      setGroupName(item.group);
    } else {
      setEditGroupData(null);
      setGroupName("");
    }
    setOpenGroupDialog(true);
  };

  const handleCloseGroupDialog = () => {
    setOpenGroupDialog(false);
    setEditGroupData(null);
    setGroupName("");
  };

  // ──────────────────────────────────────────
  // 二、標籤管理
  // ──────────────────────────────────────────
  const [labelList, setLabelList] = useState([]);
  const [openLabelDialog, setOpenLabelDialog] = useState(false);
  const [editLabelData, setEditLabelData] = useState(null);
  const [labelTitle, setLabelTitle] = useState("");
  const [labelGroupId, setLabelGroupId] = useState("");
  const [flatPrice, setFlatPrice] = useState(0);
  const [dynamicPrice, setDynamicPrice] = useState(0);
  const [extendedHourPrice, setExtendedHourPrice] = useState(0);
  const [isFlat, setIsFlat] = useState(false);
  const [isDynamic, setIsDynamic] = useState(false);

  // 2.1 取得標籤（同樣來自 fetchGroupsAndLabels，做 flatten）
  const fetchLabels = () => {
    fetchGroupsAndLabels()
      .then((res) => {
        if (res?.success) {
          const groupArr = res.data || [];
          const flatten = [];
          groupArr.forEach((g) => {
            const { group_id, group, label_responses } = g;
            (label_responses || []).forEach((lb) => {
              flatten.push({
                ...lb,
                group_id,
                group_name: group,
              });
            });
          });
          setLabelList(flatten);
        } else {
          showSnackbar("取得標籤失敗", "error");
        }
      })
      .catch((err) => {
        console.error("fetchLabels error", err);
        showSnackbar("取得標籤列表錯誤", "error");
      });
  };

  // 2.2 建立標籤
  const handleCreateLabel = () => {
    if (!labelTitle.trim() || !labelGroupId) {
      showSnackbar("請填寫標籤名稱 & 群組", "warning");
      return;
    }
    const payload = {
      group_id: Number(labelGroupId),
      title: labelTitle,
      flat_price: Number(flatPrice),
      dynamic_price: Number(dynamicPrice),
      extended_hour_price: Number(extendedHourPrice),
      is_flat: isFlat,
      is_dynamic: isDynamic,
    };
    createLabel(payload)
      .then((res) => {
        if (res?.success) {
          showSnackbar("新增標籤成功");
          fetchLabels();
          handleCloseLabelDialog();
        } else {
          showSnackbar("新增標籤失敗", "error");
        }
      })
      .catch((err) => {
        console.error("handleCreateLabel error", err);
        showSnackbar("新增標籤發生錯誤", "error");
      });
  };

  // 2.3 修改標籤
  const handleUpdateLabel = () => {
    if (!editLabelData) return;
    const { label_id } = editLabelData;
    if (!labelTitle.trim() || !labelGroupId) {
      showSnackbar("標籤名稱 & 群組不能為空", "warning");
      return;
    }
    const payload = {
      group_id: Number(labelGroupId),
      title: labelTitle,
      flat_price: Number(flatPrice),
      dynamic_price: Number(dynamicPrice),
      extended_hour_price: Number(extendedHourPrice),
      is_flat: isFlat,
      is_dynamic: isDynamic,
    };
    updateLabel(label_id, payload)
      .then((res) => {
        if (res?.success) {
          showSnackbar("修改標籤成功");
          fetchLabels();
          handleCloseLabelDialog();
        } else {
          showSnackbar("修改標籤失敗", "error");
        }
      })
      .catch((err) => {
        console.error("handleUpdateLabel error", err);
        showSnackbar("修改標籤錯誤", "error");
      });
  };

  // 2.4 刪除標籤
  const handleDeleteLabel = (label_id) => {
    if (!window.confirm("確認要刪除此標籤嗎？")) return;
    deleteLabel(label_id)
      .then((res) => {
        if (res?.success) {
          showSnackbar("刪除標籤成功");
          fetchLabels();
        } else {
          showSnackbar("刪除標籤失敗", "error");
        }
      })
      .catch((err) => {
        console.error("handleDeleteLabel error", err);
        showSnackbar("刪除標籤錯誤", "error");
      });
  };

  const handleOpenLabelDialog = (item) => {
    if (item) {
      // 編輯
      setEditLabelData(item);
      setLabelTitle(item.label);
      setLabelGroupId(item.group_id);
      setFlatPrice(item.flat_price ?? 0);
      setDynamicPrice(item.dynamic_price ?? 0);
      setExtendedHourPrice(item.extended_hour_price ?? 0);
      setIsFlat(item.is_flat ?? false);
      setIsDynamic(item.is_dynamic ?? false);
    } else {
      // 新增
      setEditLabelData(null);
      setLabelTitle("");
      setLabelGroupId("");
      setFlatPrice(0);
      setDynamicPrice(0);
      setExtendedHourPrice(0);
      setIsFlat(false);
      setIsDynamic(false);
    }
    setOpenLabelDialog(true);
  };
  const handleCloseLabelDialog = () => {
    setOpenLabelDialog(false);
    setEditLabelData(null);
  };

  // ──────────────────────────────────────────
  // 三、風格管理
  // ──────────────────────────────────────────
  const [styleList, setStyleList] = useState([]);
  const [openStyleDialog, setOpenStyleDialog] = useState(false);
  const [editStyleData, setEditStyleData] = useState(null);
  const [styleName, setStyleName] = useState("");

  // 3.1 取得風格列表
  const getStyles = () => {
    fetchStyles()
      .then((res) => {
        if (res?.success) {
          setStyleList(res.data || []);
        } else {
          showSnackbar("取得風格列表失敗", "error");
        }
      })
      .catch((err) => {
        console.error("getStyles error", err);
        showSnackbar("取得風格列表錯誤", "error");
      });
  };

  // 3.2 新增風格
  const handleCreateStyle = () => {
    if (!styleName.trim()) {
      showSnackbar("請輸入風格名稱", "warning");
      return;
    }
    createStyle({ style: styleName })
      .then((res) => {
        if (res?.success) {
          showSnackbar("新增風格成功");
          getStyles();
          handleCloseStyleDialog();
        } else {
          showSnackbar("新增風格失敗", "error");
        }
      })
      .catch((err) => {
        console.error("handleCreateStyle error", err);
        showSnackbar("新增風格錯誤", "error");
      });
  };

  // 3.3 修改風格
  const handleUpdateStyle = () => {
    if (!editStyleData) return;
    const { id } = editStyleData;
    if (!styleName.trim()) {
      showSnackbar("風格名稱不可為空", "warning");
      return;
    }
    updateStyle(id, { style: styleName })
      .then((res) => {
        if (res?.success) {
          showSnackbar("修改風格成功");
          getStyles();
          handleCloseStyleDialog();
        } else {
          showSnackbar("修改風格失敗", "error");
        }
      })
      .catch((err) => {
        console.error("handleUpdateStyle error", err);
        showSnackbar("修改風格錯誤", "error");
      });
  };

  // 3.4 刪除風格
  const handleDeleteStyle = (styleId) => {
    if (!window.confirm("確定要刪除此風格嗎？")) return;
    deleteStyle(styleId)
      .then((res) => {
        if (res?.success) {
          showSnackbar("刪除風格成功");
          getStyles();
        } else {
          showSnackbar("刪除風格失敗", "error");
        }
      })
      .catch((err) => {
        console.error("handleDeleteStyle error", err);
        showSnackbar("刪除風格錯誤", "error");
      });
  };

  const handleOpenStyleDialog = (item) => {
    if (item) {
      setEditStyleData(item);
      setStyleName(item.style);
    } else {
      setEditStyleData(null);
      setStyleName("");
    }
    setOpenStyleDialog(true);
  };
  const handleCloseStyleDialog = () => {
    setOpenStyleDialog(false);
    setEditStyleData(null);
    setStyleName("");
  };

  // ──────────────────────────────────────────
  // 初始化
  // ──────────────────────────────────────────
  useEffect(() => {
    fetchGroups();  // 取得群組
    fetchLabels();  // 取得標籤
    getStyles();    // 取得風格
  }, []);

  // ──────────────────────────────────────────
  // Render
  // ──────────────────────────────────────────
  const handleChangeTab = (e, newVal) => {
    setTabValue(newVal);
  };

  return (
    <>
      <Header />
      <LeftBar />
      <Container maxWidth="lg" sx={{ pt: 10, pb: 4 }}>
        <Paper sx={{ p: 2, mb: 4 }}>

          <Typography variant="h4" sx={{ mb: 2, fontWeight: 600 }}>
            標籤 / 群組 / 風格 管理
          </Typography>

          <Tabs value={tabValue} onChange={handleChangeTab} sx={{ mb: 3 }}>
            <Tab label="群組管理" />
            <Tab label="標籤管理" />
            <Tab label="風格管理" />
          </Tabs>

          {/* 群組管理 */}
          {tabValue === 0 && (
            <Box>
              <Paper sx={{ p: 2, mb: 2 }}>
                <Button variant="contained" onClick={() => handleOpenGroupDialog(null)}>
                  新增群組
                </Button>
              </Paper>
              <TableContainer component={Paper}>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>群組ID</TableCell>
                      <TableCell>群組名稱</TableCell>
                      <TableCell align="center">操作</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {groupList.map((item) => (
                      <TableRow key={item.group_id}>
                        <TableCell>{item.group_id}</TableCell>
                        <TableCell>{item.group}</TableCell>
                        <TableCell align="center">
                          <Stack direction="row" spacing={2} justifyContent="center">
                            <Button
                              variant="outlined"
                              onClick={() => handleOpenGroupDialog(item)}
                            >
                              編輯
                            </Button>
                            <Button
                              variant="contained"
                              color="error"
                              onClick={() => handleDeleteGroup(item.group_id)}
                            >
                              刪除
                            </Button>
                          </Stack>
                        </TableCell>
                      </TableRow>
                    ))}
                    {groupList.length === 0 && (
                      <TableRow>
                        <TableCell colSpan={3} align="center">
                          目前沒有群組資料
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </Box>
          )}

          {/* 標籤管理 */}
          {tabValue === 1 && (
            <Box>
              <Paper sx={{ p: 2, mb: 2 }}>
                <Button variant="contained" onClick={() => handleOpenLabelDialog(null)}>
                  新增標籤
                </Button>
              </Paper>
              <TableContainer component={Paper}>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>標籤ID</TableCell>
                      <TableCell>標籤名稱</TableCell>
                      <TableCell>所屬群組</TableCell>
                      <TableCell>相片價</TableCell>
                      <TableCell>影片價</TableCell>
                      <TableCell>加時價</TableCell>
                      <TableCell align="center">操作</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {labelList.map((item) => (
                      <TableRow key={item.label_id}>
                        <TableCell>{item.label_id}</TableCell>
                        <TableCell>{item.label}</TableCell>
                        <TableCell>{item.group_name}</TableCell>
                        <TableCell>{item.flat_price}</TableCell>
                        <TableCell>{item.dynamic_price}</TableCell>
                        <TableCell>{item.extended_hour_price}</TableCell>
                        <TableCell align="center">
                          <Stack direction="row" spacing={2} justifyContent="center">
                            <Button
                              variant="outlined"
                              onClick={() => handleOpenLabelDialog(item)}
                            >
                              編輯
                            </Button>
                            <Button
                              variant="contained"
                              color="error"
                              onClick={() => handleDeleteLabel(item.label_id)}
                            >
                              刪除
                            </Button>
                          </Stack>
                        </TableCell>
                      </TableRow>
                    ))}
                    {labelList.length === 0 && (
                      <TableRow>
                        <TableCell colSpan={7} align="center">
                          目前沒有標籤資料
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </Box>
          )}

          {/* 風格管理 */}
          {tabValue === 2 && (
            <Box>
              <Paper sx={{ p: 2, mb: 2 }}>
                <Button variant="contained" onClick={() => handleOpenStyleDialog(null)}>
                  新增風格
                </Button>
              </Paper>
              <TableContainer component={Paper}>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>風格ID</TableCell>
                      <TableCell>風格名稱</TableCell>
                      <TableCell align="center">操作</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {styleList.map((item) => (
                      <TableRow key={item.id}>
                        <TableCell>{item.id}</TableCell>
                        <TableCell>{item.style}</TableCell>
                        <TableCell align="center">
                          <Stack direction="row" spacing={2} justifyContent="center">
                            <Button
                              variant="outlined"
                              onClick={() => handleOpenStyleDialog(item)}
                            >
                              編輯
                            </Button>
                            <Button
                              variant="contained"
                              color="error"
                              onClick={() => handleDeleteStyle(item.id)}
                            >
                              刪除
                            </Button>
                          </Stack>
                        </TableCell>
                      </TableRow>
                    ))}
                    {styleList.length === 0 && (
                      <TableRow>
                        <TableCell colSpan={3} align="center">
                          目前沒有風格資料
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </Box>
          )}

          {/* ──────────────────────────────────────────
          群組 Dialog
         ────────────────────────────────────────── */}
          <Dialog open={openGroupDialog} onClose={handleCloseGroupDialog} fullWidth>
            <DialogTitle>{editGroupData ? "編輯群組" : "新增群組"}</DialogTitle>
            <DialogContent dividers>
              <TextField
                fullWidth
                label="群組名稱"
                sx={{ mt: 1 }}
                value={groupName}
                onChange={(e) => setGroupName(e.target.value)}
              />
            </DialogContent>
            <DialogActions>
              <Button onClick={handleCloseGroupDialog}>取消</Button>
              {editGroupData ? (
                <Button variant="contained" onClick={handleUpdateGroup}>
                  確認修改
                </Button>
              ) : (
                <Button variant="contained" onClick={handleCreateGroup}>
                  確認新增
                </Button>
              )}
            </DialogActions>
          </Dialog>

          {/* ──────────────────────────────────────────
          標籤 Dialog
         ────────────────────────────────────────── */}
          <Dialog open={openLabelDialog} onClose={handleCloseLabelDialog} fullWidth>
            <DialogTitle>{editLabelData ? "編輯標籤" : "新增標籤"}</DialogTitle>
            <DialogContent dividers>
              <Grid container spacing={2} sx={{ mt: 1 }}>
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label="標籤名稱 (title)"
                    value={labelTitle}
                    onChange={(e) => setLabelTitle(e.target.value)}
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    select
                    label="所屬群組"
                    value={labelGroupId}
                    onChange={(e) => setLabelGroupId(e.target.value)}
                    SelectProps={{ native: true }}
                  >
                    <option value="">請選擇</option>
                    {groupList.map((g) => (
                      <option key={g.group_id} value={g.group_id}>
                        {g.group}
                      </option>
                    ))}
                  </TextField>
                </Grid>
                <Grid item xs={12} sm={4}>
                  <TextField
                    fullWidth
                    label="相片價 (flat_price)"
                    type="number"
                    value={flatPrice}
                    onChange={(e) => setFlatPrice(e.target.value)}
                  />
                </Grid>
                <Grid item xs={12} sm={4}>
                  <TextField
                    fullWidth
                    label="影片價 (dynamic_price)"
                    type="number"
                    value={dynamicPrice}
                    onChange={(e) => setDynamicPrice(e.target.value)}
                  />
                </Grid>
                <Grid item xs={12} sm={4}>
                  <TextField
                    fullWidth
                    label="加時價 (extended_hour_price)"
                    type="number"
                    value={extendedHourPrice}
                    onChange={(e) => setExtendedHourPrice(e.target.value)}
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <FormControlLabel
                    control={
                      <Checkbox
                        checked={isFlat}
                        onChange={(e) => setIsFlat(e.target.checked)}
                      />
                    }
                    label="啟用相片"
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <FormControlLabel
                    control={
                      <Checkbox
                        checked={isDynamic}
                        onChange={(e) => setIsDynamic(e.target.checked)}
                      />
                    }
                    label="啟用影片"
                  />
                </Grid>
              </Grid>
            </DialogContent>
            <DialogActions>
              <Button onClick={handleCloseLabelDialog}>取消</Button>
              {editLabelData ? (
                <Button variant="contained" onClick={handleUpdateLabel}>
                  確認修改
                </Button>
              ) : (
                <Button variant="contained" onClick={handleCreateLabel}>
                  確認新增
                </Button>
              )}
            </DialogActions>
          </Dialog>

          {/* ──────────────────────────────────────────
          風格 Dialog
         ────────────────────────────────────────── */}
          <Dialog open={openStyleDialog} onClose={handleCloseStyleDialog} fullWidth>
            <DialogTitle>{editStyleData ? "編輯風格" : "新增風格"}</DialogTitle>
            <DialogContent dividers>
              <TextField
                fullWidth
                label="風格名稱 (style)"
                sx={{ mt: 1 }}
                value={styleName}
                onChange={(e) => setStyleName(e.target.value)}
              />
            </DialogContent>
            <DialogActions>
              <Button onClick={handleCloseStyleDialog}>取消</Button>
              {editStyleData ? (
                <Button variant="contained" onClick={handleUpdateStyle}>
                  確認修改
                </Button>
              ) : (
                <Button variant="contained" onClick={handleCreateStyle}>
                  確認新增
                </Button>
              )}
            </DialogActions>
          </Dialog>

          {/* ──────────────────────────────────────────
          Snackbar
         ────────────────────────────────────────── */}
          <Snackbar
            open={snackbarOpen}
            autoHideDuration={3000}
            onClose={handleCloseSnackbar}
            anchorOrigin={{ vertical: "top", horizontal: "center" }}
          >
            <Alert severity={snackbarSeverity} onClose={handleCloseSnackbar} sx={{ width: "100%" }}>
              {snackbarMsg}
            </Alert>
          </Snackbar>
        </Paper>
      </Container>

    </>

  );
};

export default LabelManagement;
