import { Button, TextField, Typography } from "@mui/material";
import { useMemo, useState } from "react";
import { useLocation } from "react-router-dom";
import { service } from "../../../api";
import { StyledBox, StyledFlexBox } from "../../../styles/Shared.styles";

const safeJsonParse = (text) => {
  if (!text?.trim()) return { ok: true, value: undefined };
  try {
    return { ok: true, value: JSON.parse(text) };
  } catch (error) {
    return { ok: false, error };
  }
};

const getErrorPayload = (error) => {
  const status = error?.response?.status;
  const data = error?.response?.data;
  if (status || data) return { status, data };
  return { message: error?.message || String(error) };
};

const ApiBlock = ({
  title,
  url,
  setUrl,
  paramsText,
  setParamsText,
  run,
  loading,
  result,
  error,
}) => {
  const parsedParams = useMemo(() => safeJsonParse(paramsText), [paramsText]);

  return (
    <StyledBox
      bg="#fff"
      p={24}
      borderRadius="16px"
      boxShadow="0px 2px 20px rgba(0, 0, 0, 0.05)"
      width="100%"
      maxWidth={900}
      mb={16}
    >
      <StyledFlexBox justifyContent="space-between" alignItems="center" mb={16}>
        <Typography variant="h6" sx={{ fontWeight: 700 }}>
          {title}
        </Typography>
        <Button
          variant="contained"
          disabled={loading || !url?.trim() || !parsedParams.ok}
          onClick={run}
        >
          {loading ? "請稍等…" : "GET"}
        </Button>
      </StyledFlexBox>

      <TextField
        fullWidth
        label="API URL（相對於 HOST，例如 /api/xxx）"
        value={url}
        onChange={(e) => setUrl(e.target.value)}
        size="small"
        sx={{ mb: 2 }}
      />

      <TextField
        fullWidth
        label="Query Params（JSON，可留空）"
        value={paramsText}
        onChange={(e) => setParamsText(e.target.value)}
        size="small"
        multiline
        minRows={3}
        error={!parsedParams.ok}
        helperText={
          parsedParams.ok ? "例如：{\"page\":1,\"limit\":10}" : "JSON 格式錯誤"
        }
        sx={{ mb: 2 }}
      />

      <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 1 }}>
        Response
      </Typography>
      <StyledBox
        as="pre"
        p={16}
        bg="#F6F7FB"
        borderRadius="12px"
        overflow="auto"
        style={{ margin: 0, whiteSpace: "pre-wrap", wordBreak: "break-word" }}
      >
        {error
          ? JSON.stringify(error, null, 2)
          : result
            ? JSON.stringify(result, null, 2)
            : "尚未呼叫"}
      </StyledBox>
    </StyledBox>
  );
};

const ApiGetTester = () => {
  const location = useLocation();
  const query = useMemo(() => new URLSearchParams(location.search), [location]);

  const [api1Url, setApi1Url] = useState(query.get("api1") || "");
  const [api2Url, setApi2Url] = useState(query.get("api2") || "");
  const [api1ParamsText, setApi1ParamsText] = useState(query.get("p1") || "");
  const [api2ParamsText, setApi2ParamsText] = useState(query.get("p2") || "");

  const [api1Loading, setApi1Loading] = useState(false);
  const [api2Loading, setApi2Loading] = useState(false);

  const [api1Result, setApi1Result] = useState(null);
  const [api2Result, setApi2Result] = useState(null);

  const [api1Error, setApi1Error] = useState(null);
  const [api2Error, setApi2Error] = useState(null);

  const runApi1 = async () => {
    const parsed = safeJsonParse(api1ParamsText);
    if (!parsed.ok) return;
    setApi1Loading(true);
    setApi1Error(null);
    try {
      const res = await service({ url: api1Url, method: "get", params: parsed.value });
      setApi1Result(res?.data ?? res);
    } catch (error) {
      setApi1Error(getErrorPayload(error));
    } finally {
      setApi1Loading(false);
    }
  };

  const runApi2 = async () => {
    const parsed = safeJsonParse(api2ParamsText);
    if (!parsed.ok) return;
    setApi2Loading(true);
    setApi2Error(null);
    try {
      const res = await service({ url: api2Url, method: "get", params: parsed.value });
      setApi2Result(res?.data ?? res);
    } catch (error) {
      setApi2Error(getErrorPayload(error));
    } finally {
      setApi2Loading(false);
    }
  };

  const runBoth = async () => {
    await Promise.all([runApi1(), runApi2()]);
  };

  return (
    <StyledFlexBox
      flexDirection="column"
      alignItems="center"
      bg="#F6F7FB"
      minHeight="100vh"
      p={24}
    >
      <StyledFlexBox
        width="100%"
        maxWidth={900}
        justifyContent="space-between"
        alignItems="center"
        mb={16}
      >
        <Typography variant="h5" sx={{ fontWeight: 800, color: "#004B97" }}>
          API GET 測試頁
        </Typography>
        <Button
          variant="outlined"
          disabled={api1Loading || api2Loading}
          onClick={runBoth}
        >
          兩隻一起打
        </Button>
      </StyledFlexBox>

      <ApiBlock
        title="API #1"
        url={api1Url}
        setUrl={setApi1Url}
        paramsText={api1ParamsText}
        setParamsText={setApi1ParamsText}
        run={runApi1}
        loading={api1Loading}
        result={api1Result}
        error={api1Error}
      />

      <ApiBlock
        title="API #2"
        url={api2Url}
        setUrl={setApi2Url}
        paramsText={api2ParamsText}
        setParamsText={setApi2ParamsText}
        run={runApi2}
        loading={api2Loading}
        result={api2Result}
        error={api2Error}
      />
    </StyledFlexBox>
  );
};

export default ApiGetTester;

