import { createTheme, ThemeProvider } from "@mui/material";
import "react-datepicker/dist/react-datepicker.css";
import { Route, BrowserRouter as Router, Routes } from "react-router-dom";
import { GlobalStyle, ResetStyle } from "./components/globalStyle";
import Label from "./containers/Admin/Label";
import Member from "./containers/Admin/Member";
import Order from "./containers/Admin/Order";
import ApiGet from "./containers/Admin/ApiGet";
import Setting from "./containers/Admin/Setting";
import AppVersion from "./containers/Admin/AppVersion";
import Login from "./containers/Login";



import OverView from "./containers/Member/OverView";
import ApiGetTester from "./containers/Tools/ApiGetTester";

function App() {
  const theme = createTheme({
    components: {
      MuiOutlinedInput: {
        styleOverrides: {
          notchedOutline: {
            border: "1px solid #fff",
            borderRadius: "100px",
            backgroundColor: "#fff",
            zIndex: -1,
          },
        },
      },
      MuiDialog: {
        styleOverrides: {
          paper: {
            maxWidth: "fit-content",
          },
        },
      },
      MuiButton: {
        styleOverrides: {
          root: {
            width: "120px",
          },
          containedPrimary: {
            backgroundColor: "#8C9EFF",
            borderRadius: "100px",
            width: 120,
            height: 40,
            fontSize: 14,
            boxShadow: "none",
            "&.Mui-disabled": {
              backgroundColor: "#D7E0FF",
              color: "#fff",
            },
          },
          outlinedPrimary: {
            color: "#A7A7A7",
            borderColor: "#A7A7A7",
          },
          outlined: {
            borderRadius: "100px",
            width: 120,
            height: 40,
            fontSize: 14,
            boxShadow: "none",
          },
        },
      },
      MuiTableRow: {
        styleOverrides: {
          head: {
            height: 80,
          },
        },
      },
      MuiTableCell: {
        styleOverrides: {
          head: {
            color: "#505050",
          },
          body: {
            color: "#7C7C7C",
            height: 80,
          },
        },
      },
      MuiRadio: {
        styleOverrides: {
          colorPrimary: {
            color: "#8C9EFF",
            "&.Mui-checked": {
              color: "#8C9EFF",
            },
          },
        },
      },
      MuiFormControlLabel: {
        styleOverrides: {
          label: {
            color: "#505050",
          },
        },
      },
      MuiAlert: {
        styleOverrides: {
          standard: {
            alignItems: "center",
            fontSize: "14px",
          },
        },
      },
    },
  });

  return (
    <ThemeProvider theme={theme}>
        <div className="App">
          <ResetStyle />
          <GlobalStyle />
          <Router>
            <Routes>
              <Route element={<Setting />} path={"/setting"} />
              <Route element={<AppVersion />} path={"/app-version"} />
              <Route element={<Label />} path={"/label"} />
              <Route element={<Member />} path={"/member"} />
              <Route element={<Order />} path={"/order"} />
              <Route element={<ApiGet />} path={"/api-get"} />
            </Routes>
            <Routes>
              <Route element={<Login />} path={"/"} />
              <Route element={<OverView />} path={"/OverView"} />
              <Route element={<ApiGetTester />} path={"/api-get-tester"} />
            </Routes>
          </Router>
        </div>
    </ThemeProvider>
  );
}

export default App;
