// api/OrderAPI.js
import { service } from "."; // 依你的實際路徑

/**
 * 取得訂單列表 (GET /bo/purchase)
 * 可帶 query 參數：
 * purchaseType: WAIT | ACCEPT | DOING | SUCCESS | CANCEL
 * payType: NO_PAY | SUCCESS | FAIL | APPLY_REFUND | REFUND
 * page, limit, order, sort
 */
export const fetchOrderList = (params = {}) => {
  return new Promise((resolve, reject) => {
    let url = "/bo/purchase?";
    const queryArr = [];

    if (params.purchaseType) queryArr.push("purchaseType=" + params.purchaseType);
    if (params.payType) queryArr.push("payType=" + params.payType);
    if (params.page) queryArr.push("page=" + params.page);
    if (params.limit) queryArr.push("limit=" + params.limit);
    if (params.order) queryArr.push("order=" + params.order);
    if (params.sort) queryArr.push("sort=" + params.sort);
    if (params.begin_date ) queryArr.push("begin_date=" + params.begin_date );
    if (params.end_date) queryArr.push("end_date=" + params.end_date);
    if (params.is_charge) queryArr.push("is_charge=" + params.is_charge);
    
    url += queryArr.join("&");

    service({
      url,
      method: "GET",
    })
      .then(async (res) => await resolve(res.data))
      .catch((err) => reject(err));
  });
};



export const updatePurchaseIsCharge = (id,is_charge) => {
  return new Promise((resolve, reject) => {
    let url = "/bo/purchase/is_charge/"+id+"?";
    const queryArr = [];
    queryArr.push("is_charge=" + is_charge );
    url += queryArr.join("&");

    service({
      url,
      method: "PUT",
    })
      .then(async (res) => await resolve(res.data))
      .catch((err) => reject(err));
  });
};

export const forceSuccessPurchase = (purchaseId) => {
  return new Promise((resolve, reject) => {
    service({
      url: `/bo/purchase/force_success/${purchaseId}`,
      method: "PUT",
    })
      .then(async (res) => await resolve(res.data))
      .catch((err) => reject(err));
  });
};
