import React, { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Container,
  Divider,
  Paper,
  Snackbar,
  Stack,
  TextField,
  Typography,
} from "@mui/material";
import Header from "../../../components/AdminHeader";
import LeftBar from "../../../components/AdminLeftBar";
import { createAppVersion, fetchLatestAppVersion } from "../../../api/AppVersion";

const AppVersion = () => {
  const [latestLoading, setLatestLoading] = useState(false);
  const [latestVersion, setLatestVersion] = useState("");
  const [latestRaw, setLatestRaw] = useState(null);

  const [createLoading, setCreateLoading] = useState(false);
  const [version, setVersion] = useState("");
  const [note, setNote] = useState("");

  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMessage, setSnackbarMessage] = useState("");
  const [snackbarSeverity, setSnackbarSeverity] = useState("success");

  const canCreate = useMemo(() => version.trim().length > 0, [version]);

  const showSnackbar = (message, severity = "success") => {
    setSnackbarMessage(message);
    setSnackbarSeverity(severity);
    setSnackbarOpen(true);
  };

  const getLatest = async () => {
    setLatestLoading(true);
    try {
      const res = await fetchLatestAppVersion();
      setLatestRaw(res);
      if (res?.success) {
        setLatestVersion(res?.data?.version || "");
      } else {
        setLatestVersion("");
        showSnackbar(res?.message || "查詢失敗", "error");
      }
    } catch (error) {
      setLatestVersion("");
      showSnackbar("查詢失敗", "error");
    } finally {
      setLatestLoading(false);
    }
  };

  const handleCreate = async () => {
    if (!canCreate) {
      showSnackbar("請輸入 version", "warning");
      return;
    }

    setCreateLoading(true);
    try {
      const res = await createAppVersion({ version: version.trim(), note: note.trim() });
      if (res?.success) {
        showSnackbar("建立成功", "success");
        setVersion("");
        setNote("");
        getLatest();
      } else {
        showSnackbar(res?.message || "建立失敗", "error");
      }
    } catch (error) {
      showSnackbar("建立失敗", "error");
    } finally {
      setCreateLoading(false);
    }
  };

  const handleCloseSnackbar = () => setSnackbarOpen(false);

  useEffect(() => {
    getLatest();
  }, []);

  return (
    <>
      <Header />
      <LeftBar />
      <Box
        sx={{
          ml: { md: 24 },
          pt: 4,
          pb: 8,
          px: { xs: 2, md: 0 },
          background:
            "radial-gradient(1200px 300px at 10% 0%, #f3fbff 0%, transparent 60%), radial-gradient(900px 300px at 90% 0%, #fff6ed 0%, transparent 55%)",
        }}
      >
        <Container>
          <Paper
            sx={{
              p: { xs: 2, md: 3 },
              borderRadius: 3,
              border: "1px solid #e6e6e6",
              background: "linear-gradient(180deg, #ffffff 0%, #fafafa 100%)",
              boxShadow: "0 12px 30px rgba(0, 0, 0, 0.08)",
            }}
            elevation={0}
          >
            <Stack
              direction={{ xs: "column", md: "row" }}
              justifyContent="space-between"
              alignItems={{ xs: "flex-start", md: "center" }}
              spacing={2}
              sx={{
                p: 2,
                borderRadius: 2,
                background: "linear-gradient(90deg, #f7fbff 0%, #fff6ef 100%)",
                border: "1px solid #e9eef5",
                mb: 3,
              }}
            >
              <Box>
                <Typography variant="h5" sx={{ fontWeight: 700, letterSpacing: 0.3 }}>
                  App Version
                </Typography>
                <Typography sx={{ color: "#667085", mt: 0.5 }}>
                  Manage latest version and release notes.
                </Typography>
              </Box>
              <Button variant="contained" onClick={getLatest} disabled={latestLoading}>
                {latestLoading ? "查詢中..." : "重新查詢"}
              </Button>
            </Stack>

            <Paper
              sx={{
                p: 2.5,
                mb: 3,
                borderRadius: 2,
                border: "1px solid #dfe7f3",
                background: "linear-gradient(180deg, #f7faff 0%, #ffffff 100%)",
              }}
              elevation={0}
            >
              <Typography sx={{ mb: 0.5, color: "#4b5563", fontWeight: 600 }}>最新 Version</Typography>
              <Typography sx={{ color: "#1f2937", fontSize: 20, fontWeight: 700 }}>
                {latestVersion ? latestVersion : "（無資料）"}
              </Typography>
            </Paper>

            <Paper
              sx={{
                p: 2.5,
                borderRadius: 2,
                border: "1px solid #e6e6e6",
                background: "#ffffff",
              }}
              elevation={0}
            >
              <Stack spacing={1} sx={{ mb: 2 }}>
                <Typography sx={{ color: "#4b5563", fontWeight: 600 }}>建立 Version</Typography>
                <Divider />
              </Stack>
              <Stack spacing={2} sx={{ maxWidth: 520 }}>
                <TextField
                  label="version"
                  value={version}
                  onChange={(e) => setVersion(e.target.value)}
                  placeholder="例如：1.2.3"
                  fullWidth
                  sx={{ background: "#ffffff", borderRadius: 1 }}
                />
                <TextField
                  label="note"
                  value={note}
                  onChange={(e) => setNote(e.target.value)}
                  placeholder="選填"
                  multiline
                  minRows={3}
                  fullWidth
                  sx={{ background: "#ffffff", borderRadius: 1 }}
                />
                <Stack direction={{ xs: "column", sm: "row" }} spacing={2}>
                  <Button variant="contained" onClick={handleCreate} disabled={!canCreate || createLoading}>
                    {createLoading ? "建立中..." : "建立"}
                  </Button>
                  <Button
                    variant="outlined"
                    onClick={() => {
                      setVersion("");
                      setNote("");
                      setLatestRaw(null);
                    }}
                    disabled={createLoading}
                  >
                    清空
                  </Button>
                </Stack>
              </Stack>
            </Paper>

            {latestRaw ? (
              <Paper
                sx={{
                  p: 2,
                  mt: 3,
                  borderRadius: 2,
                  border: "1px dashed #d7d7d7",
                  bgcolor: "#fafafa",
                }}
                elevation={0}
              >
                <Typography sx={{ mb: 1, color: "#4b5563", fontWeight: 600 }}>Response</Typography>
                <pre style={{ margin: 0, whiteSpace: "pre-wrap", wordBreak: "break-word" }}>
                  {JSON.stringify(latestRaw, null, 2)}
                </pre>
              </Paper>
            ) : null}

            <Snackbar
              open={snackbarOpen}
              autoHideDuration={3000}
              onClose={handleCloseSnackbar}
              anchorOrigin={{ vertical: "top", horizontal: "center" }}
            >
              <Alert onClose={handleCloseSnackbar} severity={snackbarSeverity} sx={{ width: "100%" }}>
                {snackbarMessage}
              </Alert>
            </Snackbar>
          </Paper>
        </Container>
      </Box>
    </>
  );
};

export default AppVersion;
