import React, { useEffect, useState } from "react";
import {
  fetchGroupsAndLabels,
} from "../../../../src/api/Label";
import {
  createVideo,
  deleteVideo,
  fetchVideoList,
  fetchVerifyUrl,
  updateVideo,
  updateVerifyUrl,
} from "../../../../src/api/setting";
import Header from "../../../components/AdminHeader";
import LeftBar from "../../../components/AdminLeftBar";

// MUI
import {
  Alert,
  Button,
  Container,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Grid,
  MenuItem,
  Paper,
  Snackbar,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from "@mui/material";

const VideoManagement = () => {
  // 1. 影片列表
  const [videoList, setVideoList] = useState([]);

  // 實名驗證網址
  const [verifyUrl, setVerifyUrl] = useState("");
  const [verifyUrlPayloadKey, setVerifyUrlPayloadKey] = useState("url");
  const [verifyUrlLoading, setVerifyUrlLoading] = useState(false);
  const [verifyUrlSaving, setVerifyUrlSaving] = useState(false);

  // 2. 用於下拉選擇的「標籤」列表 (從 /bo/label 攤平後取得)
  const [labelList, setLabelList] = useState([]);

  // 新增影片表單
  const [newUrl, setNewUrl] = useState("");
  const [newTag, setNewTag] = useState(""); // 這裡用 label 或 label，看你需求

  // 編輯 Dialog
  const [openEditDialog, setOpenEditDialog] = useState(false);
  const [editData, setEditData] = useState(null); // { id, url, tag }

  // Snackbar
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMessage, setSnackbarMessage] = useState("");
  const [snackbarSeverity, setSnackbarSeverity] = useState("success");

  // ─────────────────────────────────────────────────────────
  // useEffect：載入影片列表、標籤列表
  // ─────────────────────────────────────────────────────────
  useEffect(() => {
    getVideoData();
    getLabelData();
    getVerifyUrl();
  }, []);

  // 取得影片列表
  const getVideoData = async () => {
    try {
      const res = await fetchVideoList();
      if (res?.success) {
        setVideoList(res.data || []);
      } else {
        showSnackbar("取得影片列表失敗", "error");
      }
    } catch (err) {
      console.error("fetchVideoList error", err);
      showSnackbar("取得影片列表發生錯誤", "error");
    }
  };

  // 取得實名驗證網址
  const getVerifyUrl = async () => {
    setVerifyUrlLoading(true);
    try {
      const res = await fetchVerifyUrl();
      if (res?.success) {
        const data = res?.data;

        if (typeof data === "string") {
          setVerifyUrl(data);
          setVerifyUrlPayloadKey("url");
        } else if (data && typeof data === "object") {
          if (typeof data.verify_url === "string") {
            setVerifyUrl(data.verify_url);
            setVerifyUrlPayloadKey("verify_url");
          } else if (typeof data.url === "string") {
            setVerifyUrl(data.url);
            setVerifyUrlPayloadKey("url");
          } else {
            setVerifyUrl("");
            setVerifyUrlPayloadKey("url");
          }
        } else {
          setVerifyUrl("");
          setVerifyUrlPayloadKey("url");
        }
      } else {
        showSnackbar("取得實名驗證網址失敗", "error");
      }
    } catch (err) {
      console.error("fetchVerifyUrl error", err);
      showSnackbar("取得實名驗證網址發生錯誤", "error");
    } finally {
      setVerifyUrlLoading(false);
    }
  };

  const handleSaveVerifyUrl = async () => {
    if (!verifyUrl.trim()) {
      showSnackbar("請輸入實名驗證網址", "warning");
      return;
    }
    setVerifyUrlSaving(true);
    try {
      const res = await updateVerifyUrl({ [verifyUrlPayloadKey || "url"]: verifyUrl.trim() });
      if (res?.success) {
        showSnackbar("實名驗證網址已更新", "success");
        getVerifyUrl();
      } else {
        showSnackbar("更新實名驗證網址失敗", "error");
      }
    } catch (err) {
      console.error("updateVerifyUrl error", err);
      showSnackbar("更新實名驗證網址發生錯誤", "error");
    } finally {
      setVerifyUrlSaving(false);
    }
  };

  // 取得群組 + 標籤列表，並攤平成單一陣列
  const getLabelData = async () => {
    try {
      const res = await fetchGroupsAndLabels();
      if (res?.success) {
        const groupArray = res.data || [];
        // 攤平所有的 label_responses
        let flattenedLabels = [];
        groupArray.forEach((g) => {
          if (g.label_responses && Array.isArray(g.label_responses)) {
            g.label_responses.forEach((labelObj) => {
              flattenedLabels.push({
                label: labelObj.label,
                label_name: labelObj.label,
                group_id: g.group_id,
                group_name: g.group,
                // 也可放 flat_price / dynamic_price 等資訊
              });
            });
          }
        });
        setLabelList(flattenedLabels);
      } else {
        showSnackbar("取得標籤列表失敗", "error");
      }
    } catch (error) {
      console.error("fetchGroupsAndLabels Error", error);
      showSnackbar("取得標籤列表發生錯誤", "error");
    }
  };

  // ─────────────────────────────────────────────────────────
  // 新增影片
  // ─────────────────────────────────────────────────────────
  const handleCreate = async () => {
    if (!newUrl.trim()) {
      showSnackbar("請輸入影片 URL", "warning");
      return;
    }
    if (!newTag) {
      showSnackbar("請選擇影片標籤", "warning");
      return;
    }

    try {
      // 假設後端預期 tag 傳入 label
      // 如果後端要傳 label 文字，就把 newTag 直接設為 labelItem.label_name
      const res = await createVideo({
        url: newUrl,
        tag: newTag, // label 或 label_name，依後端規格
      });

      if (res?.success) {
        showSnackbar("新增影片成功！", "success");
        setNewUrl("");
        setNewTag("");
        getVideoData();
      } else {
        showSnackbar("新增影片失敗", "error");
      }
    } catch (err) {
      console.error("createVideo error", err);
      showSnackbar("新增影片發生錯誤", "error");
    }
  };

  // ─────────────────────────────────────────────────────────
  // 編輯影片
  // ─────────────────────────────────────────────────────────
  const handleOpenEdit = (item) => {
    setEditData({ ...item });
    setOpenEditDialog(true);
  };
  const handleCloseEditDialog = () => {
    setOpenEditDialog(false);
    setEditData(null);
  };
  const handleUpdate = async () => {
    if (!editData) return;
    const { id, url, tag } = editData;

    if (!url.trim()) {
      showSnackbar("影片 URL 不可為空", "warning");
      return;
    }
    if (!tag) {
      showSnackbar("請選擇影片標籤", "warning");
      return;
    }

    try {
      const res = await updateVideo(id, { url, tag });
      if (res?.success) {
        showSnackbar("影片修改成功", "success");
        handleCloseEditDialog();
        getVideoData();
      } else {
        showSnackbar("影片修改失敗", "error");
      }
    } catch (err) {
      console.error("updateVideo error", err);
      showSnackbar("修改影片發生錯誤", "error");
    }
  };

  // ─────────────────────────────────────────────────────────
  // 刪除影片
  // ─────────────────────────────────────────────────────────
  const handleDelete = async (id) => {
    if (!window.confirm("確定要刪除這支影片嗎？")) return;

    try {
      const res = await deleteVideo(id);
      if (res?.success) {
        showSnackbar("刪除成功", "success");
        getVideoData();
      } else {
        showSnackbar("刪除失敗", "error");
      }
    } catch (err) {
      console.error("deleteVideo error", err);
      showSnackbar("刪除發生錯誤", "error");
    }
  };

  // ─────────────────────────────────────────────────────────
  // Snackbar
  // ─────────────────────────────────────────────────────────
  const showSnackbar = (msg, severity = "info") => {
    setSnackbarMessage(msg);
    setSnackbarSeverity(severity);
    setSnackbarOpen(true);
  };
  const handleCloseSnackbar = () => {
    setSnackbarOpen(false);
  };

  // ─────────────────────────────────────────────────────────
  // Render
  // ─────────────────────────────────────────────────────────
  return (
    <>
      <Header />
      <LeftBar />
      <Container maxWidth="lg" sx={{ pt: 10, pb: 4 }}>
        <Paper sx={{ p: 2, mb: 4 }}>
          <Typography variant="h4" sx={{ mb: 2, fontWeight: 600 }}>
            影片管理
          </Typography>

          {/* 首頁：實名驗證網址 */}
          <Paper sx={{ p: 3, mb: 3 }} elevation={1}>
            <Typography variant="h6" sx={{ mb: 2 }}>
              首頁設定
            </Typography>
            <Grid container spacing={2} alignItems="center">
              <Grid item xs={12} md={8}>
                <TextField
                  fullWidth
                  label="實名驗證網址"
                  value={verifyUrl}
                  onChange={(e) => setVerifyUrl(e.target.value)}
                  disabled={verifyUrlLoading || verifyUrlSaving}
                />
              </Grid>
              <Grid item xs={12} md={4} display="flex" gap={2} alignItems="center">
                <Button
                  variant="outlined"
                  onClick={getVerifyUrl}
                  disabled={verifyUrlLoading || verifyUrlSaving}
                >
                  重新載入
                </Button>
                <Button
                  variant="contained"
                  onClick={handleSaveVerifyUrl}
                  disabled={verifyUrlLoading || verifyUrlSaving}
                >
                  儲存
                </Button>
              </Grid>
            </Grid>
          </Paper>

          {/* 新增影片 */}
          <Paper sx={{ p: 3, mb: 3 }} elevation={1}>
            <Typography variant="h6" sx={{ mb: 2 }}>
              新增影片
            </Typography>
            <Grid container spacing={2}>
              <Grid item xs={12} sm={6} md={4}>
                <TextField
                  fullWidth
                  label="影片連結 (URL)"
                  value={newUrl}
                  onChange={(e) => setNewUrl(e.target.value)}
                />
              </Grid>

              {/* 標籤下拉選單 */}
              <Grid item xs={12} sm={6} md={4}>
                <TextField
                  select
                  fullWidth
                  label="影片標籤 (Tag)"
                  value={newTag}
                  onChange={(e) => setNewTag(e.target.value)}
                >
                  <MenuItem value="">請選擇標籤</MenuItem>
                  {labelList.map((lbl) => (
                    <MenuItem key={lbl.label} value={lbl.label}>
                      {/* 可以顯示群組 + 標籤 或只顯示標籤 */}
                      {`${lbl.group_name} / ${lbl.label_name}`}
                    </MenuItem>
                  ))}
                </TextField>
              </Grid>

              <Grid item xs={12} sm={6} md={4} display="flex" alignItems="center">
                <Button variant="contained" onClick={handleCreate}>
                  新增
                </Button>
              </Grid>
            </Grid>
          </Paper>

          {/* 影片列表 */}
          <Paper sx={{ p: 2 }} elevation={1}>
            <Typography variant="h6" sx={{ mb: 2 }}>
              影片列表
            </Typography>
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>編號(ID)</TableCell>
                    <TableCell>影片連結(URL)</TableCell>
                    <TableCell>影片標籤(Tag)</TableCell>
                    <TableCell align="center" width={200}>
                      操作
                    </TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {videoList.length > 0 ? (
                    videoList.map((item) => (
                      <TableRow key={item.id}>
                        <TableCell>{item.id}</TableCell>
                        <TableCell>{item.url}</TableCell>
                        <TableCell>{item.tag}</TableCell>
                        <TableCell align="center">
                          <Stack direction="row" spacing={2} justifyContent="center">
                            <Button
                              variant="outlined"
                              onClick={() => handleOpenEdit(item)}
                            >
                              編輯
                            </Button>
                            <Button
                              variant="contained"
                              color="error"
                              onClick={() => handleDelete(item.id)}
                            >
                              刪除
                            </Button>
                          </Stack>
                        </TableCell>
                      </TableRow>
                    ))
                  ) : (
                    <TableRow>
                      <TableCell colSpan={4} align="center">
                        目前沒有任何影片資料
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>

          {/* 編輯 Dialog */}
          <Dialog open={openEditDialog} onClose={handleCloseEditDialog} fullWidth>
            <DialogTitle>編輯影片</DialogTitle>
            <DialogContent dividers>
              {editData && (
                <Grid container spacing={2} mt={1}>
                  <Grid item xs={12}>
                    <TextField
                      fullWidth
                      label="影片連結 (URL)"
                      value={editData.url}
                      onChange={(e) =>
                        setEditData((prev) => ({ ...prev, url: e.target.value }))
                      }
                    />
                  </Grid>

                  {/* 編輯時的標籤下拉 */}
                  <Grid item xs={12}>
                    <TextField
                      select
                      fullWidth
                      label="影片標籤 (Tag)"
                      value={editData.tag || ""}
                      onChange={(e) =>
                        setEditData((prev) => ({ ...prev, tag: e.target.value }))
                      }
                    >
                      <MenuItem value="">請選擇標籤</MenuItem>
                      {labelList.map((lbl) => (
                        <MenuItem key={lbl.label} value={lbl.label}>
                          {`${lbl.group_name} / ${lbl.label_name}`}
                        </MenuItem>
                      ))}
                    </TextField>
                  </Grid>
                </Grid>
              )}
            </DialogContent>
            <DialogActions>
              <Button onClick={handleCloseEditDialog}>取消</Button>
              <Button variant="contained" onClick={handleUpdate}>
                確定修改
              </Button>
            </DialogActions>
          </Dialog>

          {/* Snackbar */}
          <Snackbar
            open={snackbarOpen}
            autoHideDuration={3000}
            onClose={handleCloseSnackbar}
            anchorOrigin={{ vertical: "top", horizontal: "center" }}
          >
            <Alert
              onClose={handleCloseSnackbar}
              severity={snackbarSeverity}
              sx={{ width: "100%" }}
            >
              {snackbarMessage}
            </Alert>
          </Snackbar>
        </Paper>
      </Container>
    </>
  );
};

export default VideoManagement;
